INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6436', 'spa', 'Pannag: producto alimenticio desconocido, posiblemente confituras o tortas especiales', 'Esta enigmática palabra aparece una sola vez en Ezequiel 27:17, en la lista de bienes que Judá e Israel comerciaban con Tiro. Se menciona junto al trigo de Minit, la miel, el aceite y el bálsamo, todos productos alimenticios. Las versiones antiguas intentaron adivinar su significado y los eruditos modernos siguen sin certeza. Algunos sugieren que era un tipo de confitura o producto especial de grano. Lo que resulta claro es que era algo lo suficientemente valioso como para figurar entre las importaciones importantes de Tiro, presumiblemente algo delicioso o lujoso que los adinerados fenicios deseaban.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6437', 'spa', 'Volverse, orientarse, preparar un camino; declinar (del tiempo); mirar, atender; vaciar; esquina.', 'Describe con mayor frecuencia el acto físico de girar el cuerpo o cambiar de dirección — como Faraón que se volvió y entró en su casa (Ex 7:23), o Moisés que se apartó para ver la zarza ardiente. Puede expresar orientación estática (hacia dónde mira algo), como los basamentos del templo en 1 Reyes 7:25. En Piel intensivo significa preparar o despejar un camino, especialmente en el célebre ''preparad camino al SEÑOR'' de Isaías 40:3. En contextos temporales, el infinitivo marca transiciones: ''al caer la tarde'' (Gn 24:63). Ocasionalmente implica prestar atención, y en raros casos describe el declinar del tiempo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6438', 'spa', 'Esquina, piedra angular o jefe; el ángulo de una estructura, una piedra de fundamento o un líder del pueblo.', 'Esquina, piedra angular o jefe; el ángulo de una estructura, una piedra de fundamento o un líder del pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6439', 'spa', 'Penuel/Peniel (''rostro de Dios''); un lugar al este del Jordán y nombre propio en Judá y Benjamín.', 'Nombre propio que significa ''rostro de Dios'', con dos variantes ortográficas: Peniel (פְּנִיאֵל, Gn 32:31) y Penuel (פְּנוּאֵל). Es célebre como el sitio al este del Jordán donde Jacob luchó con el ser divino y declaró: ''He visto a Dios cara a cara'' (Gn 32:30–31). Gedeón encontró hostilidad de los hombres de Penuel durante su persecución de los madianitas (Jue 8:8–9, 17), y Jeroboam fortificó la ciudad (1 R 12:25). El nombre también pertenece a dos individuos en las genealogías del Cronista (1 Cr 4:4; 8:25). La versión de los LXX traduce ''eidos theou'' (forma de Dios) en Génesis, preservando el significado etimológico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6440', 'spa', 'rostro, presencia, superficie; también delante de (espacial/temporal)', 'Literalmente ''rostro'', este sustantivo hebreo extremadamente frecuente se extiende a una gama notable de significados. Puede designar el rostro físico de una persona o animal, la superficie de la tierra, la presencia de Dios (especialmente en la expresión ''delante de YHWH''), la posición espacial (''enfrente de'') e incluso la prioridad temporal (''anteriormente''). Con más de 2.000 apariciones en la Biblia Hebrea, su significado central de ''rostro'' irradia hacia los dominios espacial, temporal y teológico mediante extensión metafórica natural.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6441', 'spa', 'Adentro, hacia el interior; adverbio direccional que denota interioridad espacial, especialmente del templo', 'Formado con el sufijo direccional he sobre פָּנִים (''rostro''), פְּנִימָה significa literalmente ''hacia el rostro'' desde la perspectiva de quien entra, es decir, ''hacia adentro'' o ''por dentro''. La palabra aparece casi exclusivamente en descripciones arquitectónicas del espacio sagrado, especialmente el templo de Salomón (1 Re 6:18–30) y el templo visionario de Ezequiel (Ez 40:16; 41:3). Combinada con la preposición מִן significa ''desde adentro'' (1 Re 6:19, 21), y con לְ significa ''hacia el interior'' (Ez 41:3; 2 Cr 29:16). Su asociación con el santuario interior confiere a este término espacial, por lo demás común, una cualidad sacral: ir פְּנִימָה es aproximarse al lugar santísimo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6442', 'spa', 'interior — adjetivo que describe la sección interna de un edificio, especialmente el templo o sus atrios', 'interior — adjetivo que describe la sección interna de un edificio, especialmente el templo o sus atrios');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6443', 'spa', 'Piedras preciosas, corales o perlas; gemas de gran valor usadas figuradamente para la sabiduría y la mujer virtuosa.', 'Sustantivo plural פְּנִינִים cuyo referente mineralógico exacto sigue siendo debatido: se ha identificado como corales rojos, perlas o rubíes. Lo indiscutible en cada contexto es su valor supremo. La palabra aparece casi exclusivamente en comparaciones: la sabiduría es «más preciosa que פְּנִינִים» (Pr 3:15; 8:11), el valor de la mujer virtuosa «supera con creces a פְּנִינִים» (Pr 31:10), y la verdadera sabiduría no puede comprarse con ellas (Job 28:18). Lamentaciones las utiliza por su color rojo, comparando la tez rozagante de los nobles de Sion con estas gemas (Lm 4:7). El cognado árabe fanan (''rama'') favorece la identificación con el coral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6444', 'spa', 'Peniná, segunda esposa de Elcana, rival de Ana', 'Peniná fue una de las dos esposas de Elcana, mencionada únicamente en 1 Samuel 1. Mientras Ana permanecía sin hijos, Peniná tenía descendencia y usaba esta ventaja para provocar y humillar a Ana, especialmente durante sus viajes anuales a Silo para el sacrificio. Su nombre posiblemente significa ''perla'' o ''coral'', pero su comportamiento contrasta marcadamente con cualquier connotación preciosa. Representa las dinámicas dolorosas de los hogares polígamos y sirve como contraste al sufrimiento y eventual triunfo de Ana. Después de 1 Samuel 1, desaparece de la narrativa, eclipsada por la concepción milagrosa de Samuel por Ana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6445', 'spa', 'El que mima; quien consiente o trata con excesiva indulgencia', 'Este participio Piel aparece en Proverbios 29:21, advirtiendo que «el que mima a su siervo desde la juventud, al final lo tendrá por hijo», aunque el significado de la última palabra es discutido. El término describe consentir o tratar con excesiva blandura, eliminando la disciplina y las expectativas normales. El proverbio advierte contra difuminar los límites entre amo y siervo mediante la sobreindulgencia. Un siervo criado sin estructura ni expectativas adecuadas se vuelve presuntuoso, esperando trato de hijo y heredero en lugar de aceptar su papel. La palabra captura la tendencia problemática de eximir a alguien de la disciplina necesaria, generando un sentido de derecho injustificado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6446', 'spa', 'palma (de la mano)/planta (del pie); usado en ''ketonet passim'', tunica ornamental de mangas largas', 'Sustantivo que significa la palma de la mano o la planta del pie, y que aparece exclusivamente en la expresion constructa ketonet passim, la celebre vestidura que llegaba hasta las palmas y las plantas. Jacob dio esta tunica a Jose (Gen 37:3, 23, 32), y Tamar la vestia como princesa real (2 Sam 13:18-19). La traduccion tradicional ''tunica de muchos colores'' sigue a la LXX, pero el hebreo apunta a una tunica larga hasta los tobillos y las munecas que indicaba un estatus especial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6448', 'spa', 'Atravesar, pasar entre; recorrer o examinar cuidadosamente (derivación incierta)', 'Este imperativo aparece en el Salmo 48:13, donde se exhorta a los adoradores a rodear Sion, contar sus torres, contemplar sus murallas y recorrer sus palacios. El verbo final presenta dificultades textuales; otras propuestas incluyen ''inspeccionar'' o ''considerar detenidamente''. En contexto, forma parte de una procesión litúrgica alrededor de Jerusalén, meditando en las defensas de la ciudad como evidencia de la protección divina. Sea cual sea el matiz preciso, implica una atención deliberada, posiblemente atravesando o pasando entre las estructuras para examinarlas a fondo. El salmo invita no a una observación casual, sino a una contemplación intencional de cómo Dios preserva Su ciudad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6449', 'spa', 'Pisga — montaña o cresta en Moab con vista al mar Muerto, desde donde Moisés contempló la Tierra Prometida antes de morir.', 'Pisga es un nombre geográfico que designa una montaña o cresta en el territorio de Moab, al noreste del mar Muerto, que aparece siempre con artículo definido (ha-Pisgá). Es célebre como la cumbre desde la cual Dios ordenó a Moisés contemplar la tierra de Canaán antes de su muerte (Dt 3:27; 34:1). El nombre probablemente significa ''la hendidura'' o ''la cresta'', describiendo un rasgo geológico natural. Balaam también ofreció allí sacrificios durante su encuentro con Balac (Nm 23:14). Sus laderas inferiores, llamadas ashdoth ha-Pisgá (''las vertientes de Pisga''), servían como marcadores de límites territoriales (Dt 3:17; 4:49; Jos 12:3; 13:20).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6450', 'spa', 'En Pas-damim: topónimo que significa ''límite de sangre'' o ''porción de sangre'', en Judá', 'Este topónimo aparece en 1 Crónicas 11:13, identificando el lugar donde uno de los valientes de David realizó una hazaña célebre al defender un campo de cebada contra los filisteos. El relato paralelo en 1 Samuel 17:1 presenta una forma ligeramente distinta (Efes-damim). El nombre probablemente significa ''límite de sangre'' o ''porción de sangre'', quizás en conmemoración de una batalla. Situado en el occidente de Judá, entre Azeca y Soco, a unos 26 kilómetros al suroeste de Jerusalén, se encontraba en la zona fronteriza donde los territorios filisteo e israelita se encontraban, lo cual explica los frecuentes conflictos y el nombre alusivo al derramamiento de sangre.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6451', 'spa', 'Abundancia, puñado; plenitud o cantidad suficiente (textualmente incierto)', 'Esta palabra aparece en el Salmo 72:16, en una visión de abundancia durante el reinado del rey ideal: ''abundancia de grano en la tierra''. El texto hebreo presenta dificultades; algunos eruditos proponen leer un término diferente derivado de otra raíz. Sea cual sea la palabra exacta, la imagen es clara: grano tan abundante que incluso en las cumbres de los montes hay plenitud. No se trata de un rendimiento agrícola ordinario, sino de una fertilidad milagrosa, semejante al Edén, donde hasta la tierra marginal produce con generosidad. El término captura la naturaleza desbordante de la bendición bajo un gobierno justo: no mera suficiencia, sino sobreabundancia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6452a', 'spa', 'Pasar por encima, saltar sobre; proteger y perdonar, especialmente en el evento de la Pascua', 'El verbo que da nombre a la Pascua: pasar por encima o saltar sobre, perdonando a quienes se hallaban bajo los dinteles marcados con sangre. Éxodo 12 registra tres veces la promesa de Dios: «pasaré de vosotros» (12:13), «el Señor pasará por encima de la puerta» (12:23) y explica que «el Señor pasó por encima de las casas» de Israel mientras hería a Egipto (12:27). Isaías extiende la imagen: Dios «pasará por encima» y protegerá a Jerusalén como aves que revolotean sobre sus crías (31:5). El verbo expresa la discriminación divina: perdonar selectivamente al pueblo del pacto mientras ejecuta juicio sobre Egipto. Este «pasar por encima» se convirtió en el evento salvífico central conmemorado anualmente, dando nombre a la fiesta definitoria de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6452b', 'spa', 'cojear, renquear o quedar lisiado (discapacidad física por lesión o defecto congénito)', 'Este verbo abarca tanto el momento de quedar lisiado (volverse cojo por una lesión) como la acción continua de cojear. El Nif''al en 2 Sam 4:4 describe cómo Mefiboset cayó y quedó permanentemente cojo. El Pi''el en 1 Re 18:26 retrata la danza cojeante de los profetas de Baal alrededor del altar, mientras que 1 Re 18:21 emplea una forma participial para describir metafóricamente el vacilar o titubear entre dos opiniones. La evidencia multilingüe confirma de manera consistente el sentido de discapacidad física y marcha deteriorada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6453', 'spa', 'Pascua: la fiesta anual que conmemora la liberación de Israel de Egipto, o el cordero sacrificial ofrecido en ella', 'Pascua: la fiesta anual que conmemora la liberación de Israel de Egipto, o el cordero sacrificial ofrecido en ella');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6454', 'spa', 'Pasea (nombre propio que significa ''el cojo'' o ''el que cojea'')', 'Nombre propio llevado por tres hombres distintos en el Israel postexílico. El nombre deriva de la raíz que significa ''cojear'' y probablemente alude a una discapacidad física. Un Pasea aparece en la genealogía de Judá (1 Cr 4:12), otro encabezó una familia postexílica que regresó de Babilonia (Esd 2:49; Neh 7:51), y un tercero fue padre de un constructor de la muralla durante el proyecto de restauración de Nehemías (Neh 3:6). La Septuaginta traduce el nombre de diversas maneras, lo cual refleja la incertidumbre sobre su pronunciación y significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6455', 'spa', 'Cojo; persona o animal con discapacidad física en los pies o las piernas, incapaz de caminar correctamente — un defecto descalificante para el sacrifi', 'Cojo; persona o animal con discapacidad física en los pies o las piernas, incapaz de caminar correctamente — un defecto descalificante para el sacrificio y el servicio sacerdotal. Describe a quien no puede caminar con normalidad debido a una lesión o deformidad congénita de las piernas o los pies. Frecuentemente emparejado con ''ciego'' (עִוֵּר) para representar todo el espectro de la discapacidad física — un binomio reflejado consistentemente en las traducciones (español cojo/ciego, inglés lame/blind). En la ley sacerdotal descalifica tanto al oficiante (Lev 21:18) como al animal sacrificial (Deut 15:21). Sin embargo, los profetas transforman esta imagen en una de esperanza: en Jeremías 31:8 Dios reúne al cojo junto con el ciego, e Isaías 35:6 promete que ''el cojo saltará como un ciervo''. Job 29:15 captura el ideal de compasión: ''Yo era pies para el cojo''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6456', 'spa', 'Imágenes talladas, ídolos grabados — objetos labrados en madera, piedra o metal para falsa adoración.', 'Imágenes talladas, ídolos grabados — objetos labrados en madera, piedra o metal para falsa adoración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6457', 'spa', 'Pasac: aserita, hijo de Jaflet en la genealogía tribal', 'Pasac aparece en 1 Crónicas 7:33, en la genealogía de Aser, identificado como uno de los hijos de Jaflet. Estas genealogías tribales cumplían múltiples funciones: establecer derechos de herencia, mantener la identidad tribal y preservar la memoria histórica aun cuando las estructuras políticas cambiaban. Aunque Pasac no desempeña ningún papel narrativo, su inclusión asegura que su línea familiar quedara documentada entre los descendientes de Aser. Para los lectores postexílicos, estas genealogías afirmaban la continuidad: las tribus no se habían perdido, sus estructuras familiares persistían y la identidad de Israel como doce tribus permanecía intacta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6458', 'spa', 'Labrar o tallar dando forma; referido a cortar tablas de piedra, piedras de construcción o esculpir un ídolo', 'Verbo que significa labrar, tallar o cincelar piedra o madera para darle una forma determinada. De modo memorable, Dios ordena a Moisés labrar dos tablas de piedra para el pacto renovado (Éx 34:1, 4; Dt 10:1, 3), un acto de artesanía sagrada que restaura lo quebrantado. La misma raíz describe la extracción de piedras de construcción para el Templo (1 R 5:18) y, en amarga ironía, la talla de un ídolo por manos humanas (Hab 2:18). El verbo abarca así desde la comisión santa hasta la idolatría vana, unidas por el acto físico de dar forma a un material resistente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6459', 'spa', 'imagen tallada, ídolo esculpido -- figura labrada en madera, piedra o metal usada en la adoración idolátrica', 'imagen tallada, ídolo esculpido -- figura labrada en madera, piedra o metal usada en la adoración idolátrica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6460', 'spa', 'salterio, arpa (instrumento triangular de cuerdas tomado del griego ψαλτήριον)', 'Instrumento musical mencionado exclusivamente en el relato de Daniel sobre el conjunto orquestal de Nabucodonosor. Se trata de un préstamo del griego (psalterion) que ingresó al arameo durante el período del exilio, y designa un instrumento triangular de cuerdas similar a un arpa o lira. Daniel 3 repite este instrumento cuatro veces como parte de la formación de la orquesta real, cuya ejecución señalaba el momento en que los súbditos debían postrarse ante la imagen de oro. El origen griego de la palabra refleja el intercambio cultural propio del exilio babilónico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6461', 'spa', 'Han desaparecido, se desvanecieron; dejaron de existir o de hallarse', 'Este verbo aparece en el Salmo 12:1, en un lamento por la desaparición de los fieles: ''los piadosos han desaparecido de entre los hombres''. El término describe una desaparición total, no simplemente una disminución, sino un aparente dejar de existir. Es más fuerte que reducirse en número; sugiere disolución, como si la categoría misma hubiera sido borrada. El salmista expresa una soledad existencial: mira a su alrededor y no encuentra a nadie piadoso ni digno de confianza. Ya sea despoblación literal o desesperación hiperbólica, el verbo captura el horror de hallarse solo en el compromiso con la fidelidad, como si los justos se hubieran desvanecido de la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6462', 'spa', 'Pispa: un aserita, hijo de Jeter en la genealogía tribal de Aser', 'Pispa aparece en 1 Crónicas 7:38 dentro de la genealogía de Aser, registrado como uno de los hijos de Jeter. Como muchos nombres en estas secciones genealógicas, Pispa carece de relato narrativo propio; su presencia en las Escrituras se limita a ser un eslabón en la cadena de familias aserítas. La inclusión de estos nombres por parte del Cronista tenía como propósito documentar la estructura tribal completa, asegurando que cada línea familiar reconocida quedara debidamente registrada. Para la comunidad postexílica, estas listas exhaustivas reafirmaban que la identidad tribal de Israel permanecía intacta a pesar de las disrupciones del exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6463', 'spa', 'Gemiré; emitir sonidos de esfuerzo o angustia, como en el parto (onomatopéyico)', 'Este verbo aparece en Isaías 42:14, donde Dios declara: «Gemiré como mujer de parto». Se trata de una palabra onomatopéyica que captura los sonidos involuntarios de un esfuerzo intenso o de profunda angustia. En este pasaje extraordinario, Dios emplea la imagen del alumbramiento para describir su intervención inminente: tras un largo período de silencio y contención, ahora «jadeará y resollará» al dar a luz la liberación. El gemido no expresa debilidad, sino esfuerzo poderoso: la tensión necesaria para engendrar algo nuevo. Humaniza a Dios al tiempo que subraya la naturaleza costosa y laboriosa de la salvación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6465', 'spa', 'Peor: un monte en Moab y la deidad asociada a su lugar de culto', 'Nombre propio con dos referentes: un monte en Moab que da al desierto, donde Balac llevo a Balaam para su ultimo oraculo (Num 23:28), y la deidad adorada en ese lugar, cuyo culto atrapo a Israel en la apostasia de Sitim (Num 25:18; 31:16). El ''incidente de Peor'' se convirtio en sinonimo de seduccion idolatrica, recordado incluso en Josue 22:17 como advertencia contra la infidelidad. El nombre probablemente se relaciona con una raiz que significa ''abrir ampliamente''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6466', 'spa', 'Hacer, obrar, trabajar; el verbo poético para la acción deliberada, las obras y la artesanía — sinónimo elevado de עָשָׂה.', 'Hacer, obrar, trabajar; el verbo poético para la acción deliberada, las obras y la artesanía — sinónimo elevado de עָשָׂה.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6467', 'spa', 'Obra, acción, hecho; en casos aislados, salario o retribución por el trabajo', 'Obra, acción, hecho; en casos aislados, salario o retribución por el trabajo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6468', 'spa', 'Obra, acción; salario, recompensa, retribución — el trabajo en sí o el pago que este merece. Un sustantivo que mantiene unida tanto la obra como su sa', 'Obra, acción; salario, recompensa, retribución — el trabajo en sí o el pago que este merece. Un sustantivo que mantiene unida tanto la obra como su salario — la acción y lo que merece. Isaías 40:10 proclama que el Señor viene con su recompensa (pe''ullah) delante de Él, mientras que Levítico 19:13 ordena que el salario del jornalero no sea retenido durante la noche. La palabra abarca naturalmente desde el trabajo concreto hasta la retribución divina: el Salmo 28:5 habla de Dios retribuyendo a los malvados conforme a sus ''obras'', y 2 Crónicas 15:7 alienta diciendo que ''vuestra obra será recompensada''. El francés ''rétribution'' y el español ''salario'' captan el lado de la paga, mientras que ''oeuvre'' y ''obra'' cubren la acción misma — juntos abarcando todo el rango semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6469', 'spa', 'Peultai: portero levita, hijo de Obed-edom en tiempos de David', 'Peultai aparece en 1 Crónicas 26:5 como uno de los hijos de Obed-edom, a quienes Dios bendijo y asignó como porteros del templo. La familia de Obed-edom recibió una bendición divina especial después de que este albergara el arca de Dios, y sus descendientes continuaron sirviendo como guardias de las puertas del santuario. Los porteros no cumplían una función meramente ceremonial: controlaban el acceso al espacio sagrado, mantenían el orden durante el culto y custodiaban los recintos santos. Peultai heredó tanto esta responsabilidad práctica como el honor de la asociación de su familia con el arca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6470', 'spa', 'empujar, impulsar, agitar; en Nifal/Hitpael, estar turbado o perturbado en espiritu', 'Verbo cuyo sentido en Qal significa empujar o impulsar, usado cuando el Espiritu de Yahve comienza a agitar a Sanson (Jue 13:25). En el Nifal y el Hitpael, el significado se desplaza hacia la perturbacion interior: el espiritu de Faraon se turbo tras sus suenos (Gen 41:8), y el espiritu de Nabucodonosor quedo tan agitado que el sueno huyo de el (Dan 2:1, 3). El salmista emplea el Nifal para expresar una profunda conmocion personal (Sal 77:4). El verbo abarca desde el impulso divino exterior hasta la angustia interior mas intensa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6471', 'spa', 'Golpe, paso, vez; sustantivo para contar repeticiones (''siete veces''); también paso, pie o base de objeto; y yunque.', 'פַּעַם es un sustantivo hebreo maravillosamente concreto que transita de lo físico a lo abstracto sin perder jamás del todo su arraigo corporal. Su núcleo etimológico es un golpe o impacto — la caída de un pie, el martillazo — y de esta raíz cinestésica se ramifica en tres direcciones. Con mayor frecuencia (más de 100 veces), sirve como palabra estándar para contar ocasiones: ''siete veces'' (שֶׁבַע פְּעָמִים), ''esta vez'' (הַפַּעַם), ''como antes'' (כְּפַעַם בְּפַעַם). Pero el origen corporal resurge vívidamente en textos poéticos: los ''pasos'' de una persona (Sal 119:133), los ''cascos'' que retumban por la ventana de la madre de Sísara (Jue 5:28), o incluso los ''pies'' que son atrapados (Sal 57:6). Un uso raro pero fascinante en Isaías 41:7 designa el yunque — lo que recibe golpes repetidos — devolviendo la palabra a su etimología percusiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6472', 'spa', 'Campanilla; pequeña campana dorada en la túnica del sumo sacerdote, alternando con granadas en el borde.', 'Sustantivo masculino פַּעֲמֹן que designa una campanilla pequeña, derivado de la raíz פעם que significa ''golpear'' o ''batir'', capturando la acción del badajo. Se usa exclusivamente para las campanillas doradas cosidas al borde de la túnica del sumo sacerdote (me''il), donde alternaban con ornamentos en forma de granada (Éx 28:33-34; 39:25-26). Su sonido anunciaba la entrada y salida del sacerdote del Lugar Santo, garantizando que «no muera» (Éx 28:35). Las traducciones a diversas lenguas emplean formas diminutivas, reflejando el carácter pequeño y tintineante de estas campanas ornamentales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6473', 'spa', 'abrir ampliamente (la boca), expresando deseo voraz, codicia o anhelo intenso', 'Este verbo describe la acción de abrir la boca de par en par, ya sea por codicia voraz (el Seol en Isa 5:14), burla hostil (Job 16:10), deseo ansioso de algo bueno (Job 29:23) o anhelo espiritual (Sal 119:131). La imagen es vívida: una boca abierta que expresa apetito o emoción intensa. En tres pasajes la boca pertenece a personas; en Isaías 5:14 se personifica la tumba insaciable. La palabra aparece tanto en contextos positivos (anhelar los mandamientos de Dios) como negativos (codicia, burla).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6474', 'spa', 'Paarai: uno de los valientes guerreros de David, oriundo de la Arabá', 'Paarai figura en 2 Samuel 23:35 como uno de los «valientes» de élite que conformaban la guardia personal de David y se distinguieron en combate. El pasaje paralelo de 1 Crónicas 11:37 registra su nombre como Naarai, lo que probablemente refleja una variante textual o una tradición alternativa. Estos guerreros provenían de orígenes y regiones diversas de todo Israel, y su lista constituye un verdadero cuadro de honor. La designación «el arbita» ubica geográficamente a Paarai, posiblemente en la región del valle del Jordán. Su inclusión entre los Treinta inmortalizó su valor al servicio del reino de David.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6475', 'spa', 'Abrir de par en par (especialmente la boca) para tragar, hablar o clamar; rescatar o liberar. Patsah es un verbo físico vívido que significa separar o', 'Abrir de par en par (especialmente la boca) para tragar, hablar o clamar; rescatar o liberar. Patsah es un verbo físico vívido que significa separar o abrir ampliamente — aplicado casi siempre a la boca, con registros emocionales radicalmente distintos. La tierra ''abre su boca'' para tragar la sangre del hermano de Caín (Gn 4:11) o para engullir a los rebeldes de Coré (Nm 16:30), y los enemigos ''abren de par en par sus bocas'' con hostilidad depredadora (Lm 2:16; Sal 22:14). Pero en el Salmo 144, la misma raíz significa ''rescátame'' (Sal 144:7, 10, 11), donde el cognado arameo petsa (''liberar'') ilumina cómo ''abrir'' se convirtió en ''soltar''. El español distingue entre abre y rescátame, confirmando el salto semántico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6476', 'spa', 'Prorrumpir en canto gozoso o grito de júbilo; en Piel, quebrar o triturar físicamente (huesos)', 'Palabra casi exclusiva de Isaías que expresa alabanza exuberante, invitando a montes, ruinas y a la Sión estéril a ''prorrumpir'' en jubiloso cántico ante la redención de Dios (Isa 44:23; 49:13; 52:9; 54:1). La imagen subyacente es la de algo que estalla de gozo incontenible. El Piel intensifica la dimensión física: en Miqueas 3:3, los líderes opresores son condenados por ''quebrar'' los huesos del pueblo como carne en una olla. El siríaco afín conserva el sentido gozoso, mientras que el árabe y el etiópico enfatizan la fractura física, revelando el puente semántico entre la explosión de júbilo y la ruptura violenta.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6477', 'spa', 'Término incierto en 1 Samuel 13:21, posiblemente relacionado con cobro, tarifa o afilado de herramientas', 'Esta palabra rara aparece únicamente en 1 Samuel 13:21, en un pasaje que describe el monopolio filisteo sobre el trabajo del metal. El texto hebreo en este punto se considera ampliamente corrupto, lo que hace incierto su significado exacto. Las interpretaciones tradicionales han sugerido «cargo» o «tarifa» por afilar herramientas, basándose en versiones antiguas y lecturas rabínicas, aunque BDB señala que estas carecen de fundamento filológico sólido. La evidencia multilingüe (charge, precio, price) refleja esta comprensión tradicional de un costo relacionado con los servicios de herrería mencionados en el contexto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6479', 'spa', 'Manchas o franjas peladas en varas, visibles en Génesis 30:37 dentro de la estrategia de cría de Jacob', 'Este sustantivo plural describe las franjas blancas o marcas descortezadas que Jacob produjo al pelar la corteza de ramas de álamo, almendro y plátano. La palabra aparece únicamente en Génesis 30:37, donde Jacob colocó estas varas rayadas frente a los rebaños de Labán junto a los abrevaderos como parte de su técnica de crianza para obtener crías manchadas y moteadas. El término proviene de una raíz que significa «pelar» y designa específicamente la madera blanca expuesta tras retirar la corteza en tiras, creando un aspecto rayado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6480', 'spa', 'Hender, rasgar, abrir violentamente; usado en el Salmo 60:2 donde Dios hace que la tierra se resquebraje', 'Este verbo significa agrietar, hender o rasgar con violencia, y está emparentado con cognados árabes de significado similar. Aparece una sola vez en la Biblia hebrea, en el Salmo 60:2, donde el salmista lamenta que Dios hizo temblar la tierra y la abrió. La imagen evoca daños de terremoto, con Dios como agente que fractura y quiebra la superficie terrestre. El verbo transmite ruptura violenta y catástrofe geológica como expresiones del juicio o la disciplina divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6481', 'spa', 'magullar, herir, golpear con impacto contundente', 'Este verbo describe lesionar mediante magullamiento o aplastamiento—heridas que rompen la piel o dañan tejido mediante impacto contundente. Deuteronomio 23:1 usa el participio pasivo para ''herido por aplastamiento''—probablemente refiriéndose a genitales dañados, descalificando de la asamblea. 1 Reyes 20:37 describe el mandato de un profeta: ''Golpéame y hiéreme''—solicitando lesión visible para crear un disfraz. Cantar de los Cantares 5:7 tiene a los guardias golpeando e hiriendo a la Sulamita mientras busca a su amado de noche. El verbo enfatiza impacto traumático y contusivo en lugar de corte limpio—lesión que deja marcas y causa dolor.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6482', 'spa', 'Herida, contusión o lesión causada por un golpe; se usa literal y figuradamente para el daño físico, espiritual o moral.', 'El sustantivo פֶּצַע designa una herida o contusión producida por un golpe o acto violento. Aparece en contextos legales, sapienciales y proféticos con fuerza tanto literal como figurada. En la ley del talión de Éxodo 21:25, ''herida por herida'' (פֶּצַע תַּחַת פָּצַע) establece la justicia proporcional ante el daño corporal. Lamec lo emplea en su siniestro alarde para referirse a un golpe mortal (Gn 4:23). Proverbios explora sus dimensiones paradójicas: las heridas de un amigo son fieles (27:6), y los golpes que hieren limpian el mal (20:30). Isaías 1:6 lo utiliza figuradamente para diagnosticar la condición espiritual de la nación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6483', 'spa', 'Hapises, nombre sacerdotal que aparece en la distribución de turnos sacerdotales en 1 Crónicas 24:15', 'Este nombre propio designa a una de las familias sacerdotales dentro de la organización del servicio del templo establecida por David. Aparece únicamente en 1 Crónicas 24:15 como el decimoquinto turno en la distribución de los veinticuatro turnos sacerdotales. La etimología del nombre es incierta, aunque podría relacionarse con raíces que significan «dispersar» o «saltar». Las traducciones griegas antiguas muestran variaciones considerables al transliterar este nombre, lo que sugiere incertidumbre sobre su pronunciación o significado incluso en la antigüedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6484', 'spa', 'Instar, presionar con insistencia; como sustantivo abstracto, obstinación o presunción.', 'El verbo פָּצַר expresa la presión insistente que una persona ejerce sobre otra, ya sea física o verbal. Lot insta a los dos ángeles a hospedarse (Gn 19:3), Jacob presiona a Esaú para que acepte su regalo (Gn 33:11), y los hijos de los profetas insisten ante Eliseo hasta que cede (2 R 2:17). Todas las ocurrencias en Qal implican insistencia interpersonal. En 1 Samuel 15:23, el infinitivo absoluto Hifil adquiere fuerza nominal abstracta —obstinación o presunción— emparejado con la rebelión contra Dios, revelando cómo la insistencia desmedida se transforma en un vicio espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6485', 'spa', 'Ser depositado, ser confiado (forma Hofal de פָּקַד), aparece una vez en Levítico 6:4', 'Esta forma verbal pasiva significa «fue depositado» o «fue confiado», y proviene de la raíz común פָּקַד, cuyo campo semántico incluye visitar, designar, contar y encomendar. En Levítico 6:4 aparece dentro de material legal relativo a la restitución por delitos contra la propiedad. La forma Hofal (pasiva del causativo) indica que algo ha sido puesto bajo la custodia de otra persona. El contexto trata de bienes confiados en depósito que luego fueron apropiados indebidamente, lo cual requiere tanto restitución como ofrenda por la culpa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6485a', 'spa', 'Atender, visitar; contar, pasar revista; nombrar, poner a cargo; castigar; faltar, estar ausente; depositar.', 'Con 302 apariciones, este verbo encarna el concepto de atención deliberada — ya sea contando (censo, 39x), nombrando para un cargo (23x), visitando con solicitud (32x) o con juicio (63x), o notando una ausencia (14x). El hilo semántico es la mirada enfocada: Dios ''visita'' a Sara para darle un hijo (Gn 21:1), Moisés ''pasa revista'' a los levitas (Nm 1:3), Samuel ''designa'' comandantes (Dt 20:9) y el SEÑOR ''castiga'' la iniquidad (Ex 20:5). Las lenguas fragmentan estos significados drásticamente: el árabe emplea عَدَّ (contar), عَيَّنَ (nombrar), افْتَقَدَ (visitar con solicitud), عَاقَبَ (castigar) y فُقِدَ (estar ausente) — cinco raíces distintas para lo que el hebreo unifica bajo el concepto único de atender a alguien o algo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6485b', 'spa', 'Cuentas, registros o inventarios relacionados con la construcción del tabernáculo en Éxodo 38:21', 'Este sustantivo plural, posiblemente derivado de la raíz פָּקַד (contar, pasar revista, designar), conlleva un sentido abstracto de «recuentos» o «registros contables», que por extensión pasó a designar los documentos o inventarios detallados. Aparece únicamente en Éxodo 38:21, al inicio de un inventario pormenorizado de los metales empleados en la construcción del tabernáculo. El término introduce la rendición de cuentas que le sigue, enumerando las contribuciones de oro, plata y bronce y su asignación a los diversos componentes del tabernáculo. Esta terminología administrativa refleja el registro meticuloso asociado con los proyectos de construcción sagrada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6486', 'spa', 'Supervisión, visitación o ajuste de cuentas; abarca castigo divino, cargo designado, censo, cuidado providencial, custodia y bienes almacenados', 'Supervisión, visitación o ajuste de cuentas; abarca castigo divino, cargo designado, censo, cuidado providencial, custodia y bienes almacenados');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6487', 'spa', 'depósito, prenda, cosa almacenada o confiada en custodia', 'Este término se refiere a algo depositado para custodia o almacenado para uso futuro—ya sean bienes confiados o provisiones reservadas para emergencias. Génesis 41:36 lo usa para grano almacenado contra el hambre—reservas que preservarán a Egipto. Levítico 5:21, 23 (6:2, 4 en español) lo emplea para propiedad depositada con un vecino para custodia, que se convierte en objeto de acción legal si se niega o se apropia indebidamente. El término implica responsabilidad fiduciaria—ya sea el estado almacenando grano para el pueblo o un individuo resguardando posesiones de un vecino. La violación de tal confianza constituye ofensa grave que requiere restitución y sacrificio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6488', 'spa', 'vigilancia, guardia, puesto de custodia; aparece como ''oficial de la guardia'' en Jeremías 37:13', 'Este sustantivo femenino designa la vigilancia, la guardia o la responsabilidad de custodiar, derivado de la raíz פָּקַד (supervisar, atender). Aparece únicamente en Jeremías 37:13, donde describe un cargo oficial: literalmente ''señor de la vigilancia''. El contexto es el intento de Jeremías de salir de Jerusalén durante el asedio babilónico, cuando fue detenido en la puerta de Benjamín por un oficial de guardia que lo acusó de desertar hacia los caldeos. El término designa un puesto de vigilancia militar o mando de guardia, referido específicamente a la supervisión de la seguridad en un punto de control.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6490', 'spa', 'Preceptos divinos, mandatos designados -- instrucciones autoritativas de Dios, casi exclusivas de los Salmos', 'Preceptos divinos, mandatos designados -- instrucciones autoritativas de Dios, casi exclusivas de los Salmos');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6491', 'spa', 'Abrir los ojos (literal o espiritualmente); en formas pasivas, que los ojos sean abiertos o permanezcan abiertos. Describe el acto deliberado de abrir', 'Abrir los ojos (literal o espiritualmente); en formas pasivas, que los ojos sean abiertos o permanezcan abiertos. Describe el acto deliberado de abrir los ojos, ya sea física o espiritualmente, con un profundo peso teológico en las Escrituras. Dios abre los ojos de Agar para ver un pozo (Gn 21:19), Eliseo ora para que los ojos de su siervo sean abiertos y vea los ejércitos celestiales (2 Re 6:17), y el salmista declara que el SEÑOR ''abre los ojos de los ciegos'' (Sal 146:8). Las formas pasivas aparecen en momentos cruciales: los ojos de Adán y Eva ''fueron abiertos'' para conocer el bien y el mal (Gn 3:7), e Isaías promete que los ojos de los ciegos ''serán abiertos'' en la restauración mesiánica (Is 35:5). El cognado árabe que significa ''florecer'' añade una bella imagen: los ojos abriéndose como flores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6492', 'spa', 'Pécaj, hijo de Remalías, rey usurpador de Israel que reinó durante la crisis siro-efraimita.', 'Nombre de un oficial militar que asesinó al rey Pecajías y tomó el trono de Israel, reinando aproximadamente entre 752 y 732 a. C. Pécaj es recordado sobre todo por su desafortunada alianza con Rezín de Damasco contra Judá, la crisis siro-efraimita que impulsó la célebre profecía del Emmanuel de Isaías (Is 7:1). Su reinado terminó cuando Oseas conspiró contra él, perpetuando el ciclo de violencia que marcó las últimas décadas de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6494', 'spa', 'Pecajías, rey de Israel, asesinado tras reinado de dos años', 'Pecajías fue rey de Israel que reinó solo dos años antes de ser asesinado. Hijo de Manahem, sucedió a su padre pero continuó el patrón del reino del norte de hacer lo malo ante los ojos de Yahveh. Su capitán Peka hijo de Remalías conspiró contra él y lo mató en la ciudadela de Samaria, junto con Argob y Arieh, ayudado por cincuenta galaaditas. Su breve y turbulento reinado (alrededor de 740-738 a.C.) ejemplifica la inestabilidad y violencia que caracterizaron las décadas finales de Israel antes de la conquista asiria. El nombre significa ''Yahveh ha abierto (los ojos)'', aunque su reinado no mostró discernimiento espiritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6496', 'spa', 'Supervisor, oficial designado; persona puesta a cargo de una tarea, grupo o institución por autoridad delegada. Derivado de la raíz פקד (''designar, vi', 'Supervisor, oficial designado; persona puesta a cargo de una tarea, grupo o institución por autoridad delegada. Derivado de la raíz פקד (''designar, visitar, pasar revista''), este sustantivo designa a alguien formalmente puesto en un rol de supervisión. Abarca ámbitos civiles, militares y sagrados: José propone comisionados sobre los almacenes de grano de Egipto (Gn 41:34), el rey de Ester designa oficiales para el harén (Est 2:3), y Pasur sirve como supervisor principal del templo (Jer 20:1). El español lo traduce variablemente como supervisor y encargado, mientras que el alemán usa Aufseher — todos capturando el sentido de autoridad institucional delegada más que soberanía inherente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6497', 'spa', 'calabazas, ornamentos en forma de calabaza (tallados decorativos)', 'Este término describe ornamentos tallados decorativos con forma de calabazas o protuberancias, que adornaban el templo de Salomón. Algunos intérpretes los ven con forma de calabaza (como pepinos silvestres), mientras otros sugieren formas de protuberancia o bola. Aparecían como parte de la elaborada ornamentación de madera y bronce del templo—tallados en el revestimiento de cedro y fundidos en el gran mar de bronce. 1 Reyes 6:18 describe tallados de cedro de calabazas y flores dentro del templo. 1 Reyes 7:24 menciona calabazas rodeando el mar de bronce, fundidas en dos filas bajo su borde. Estos elementos decorativos reflejaban las convenciones artísticas del Antiguo Cercano Oriente y contribuían al esplendor visual del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6498', 'spa', 'calabazas silvestres, probablemente coloquíntida (Citrullus colocynthis), frutos venenosos mencionados en 2 Reyes 4:39', 'Este sustantivo plural se refiere a calabazas silvestres o pepinos del campo, identificados por la mayoría de los estudiosos como coloquíntida (Citrullus colocynthis), una enredadera silvestre que produce frutos pequeños, amargos y tóxicos con propiedades purgantes. La palabra aparece únicamente en 2 Reyes 4:39, en el relato de Eliseo y el potaje envenenado. Un hombre que recolectaba hierbas durante una hambruna encontró una vid silvestre y recogió sus frutos sin percatarse del peligro. Al cortarlos y echarlos en la olla, el guiso se volvió tóxico, provocando el grito: ''¡Hay muerte en la olla!'', hasta que Eliseo neutralizó milagrosamente el veneno.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6499', 'spa', 'Novillo, becerro joven para sacrificio; figuradamente, símbolo de fuerza feroz o agresión.', 'פַּר es el término hebreo estándar para el bovino macho joven seleccionado para el sacrificio, que aparece abrumadoramente en la legislación ritual. La frase פַּר בֶּן-בָּקָר (''novillo, hijo de la vacada'') se repite como una fórmula litúrgica a lo largo de Levítico y Números, especificando la ofrenda animal individual más costosa — requerida para la consagración sacerdotal (Ex 29:1), ofrendas por el pecado (Lv 4:3) y holocaustos de festividades (Nm 28-29). En textos poéticos, la fuerza bruta del toro se convierte en metáfora de la agresión: los ''toros de Basán'' rodean al salmista sufriente (Sal 22:12), y los guerreros de Babilonia son llamados ''sus toros'' marcados para la matanza (Jr 50:27).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6500', 'spa', 'dar fruto, fructificar (forma Hifil), aparece en Oseas 13:15 con un juego de palabras sobre el nombre Efraín', 'Esta forma verbal proviene de la raíz común פָּרָה que significa ''dar fruto'' o ''ser fecundo'', la misma raíz presente en la bendición de la creación ''fructificad y multiplicaos'' (Génesis 1:22). En Oseas 13:15, la forma Hifil aparece en un contexto de amarga ironía: aunque Efraín florezca (con un juego de palabras sobre su nombre, que evoca ''fecundidad''), el viento del este del juicio se avecina. A lo largo de las Escrituras, este verbo conlleva connotaciones de productividad, prosperidad y bendición, lo que hace especialmente conmovedor su uso en este oráculo de juicio, donde la imagen de fertilidad se invierte en esterilidad y destrucción.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6501', 'spa', 'Asno salvaje (onagro); símbolo de libertad indómita, supervivencia en el desierto e independencia obstinada.', 'Designa al asno salvaje u onagro (Equus hemionus), un animal que encarnaba la libertad indómita del desierto en la imaginación del antiguo Cercano Oriente. La descripción angélica de Ismael como «un asno montés de hombre» (Gn 16:12) se convirtió en imagen proverbial de feroz independencia nómada. Los discursos de Job emplean al animal para ilustrar tanto la futilidad de la queja (Job 6:5) como la imposibilidad de domar la naturaleza innata (Job 11:12). Oseas compara al díscolo Efraín con un asno salvaje que vaga solo (Os 8:9), y Jeremías asemeja la lujuria de Israel por los ídolos a una asna montés en celo (Jer 2:24).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6502', 'spa', 'Piram, rey cananeo de Jarmut que se unió a la coalición contra Gabaón en Josué 10:3', 'Este nombre propio pertenece a uno de los cinco reyes amorreos que formaron una coalición para atacar Gabaón después de que esta hiciera las paces con Israel. Piram gobernaba Jarmut, una ciudad cananea en la Sefela, las tierras bajas al oeste de Jerusalén. Se alió con los reyes de Jerusalén, Hebrón, Laquis y Eglón en respuesta al tratado de Gabaón con Josué, considerándolo una traición estratégica. El asedio de la coalición a Gabaón desencadenó la marcha nocturna de Israel desde Gilgal y la famosa batalla en que el sol se detuvo. Los cinco reyes, incluido Piram, fueron capturados, ejecutados y sepultados en la cueva de Maqueda.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6503', 'spa', 'Parbar, columnata o estructura en el lado occidental del templo', 'Este término arquitectónico de significado incierto designa una estructura en el lado occidental del complejo del templo de Salomón. Aparece en dos formas: ''parvarim'' en 2 Reyes 23:11 y ''parbar'' en 1 Crónicas 26:18 (dos veces). Los estudiosos proponen varias interpretaciones: una columnata, pabellón abierto, arrabal o área de almacenamiento. El término puede ser un préstamo persa que significa ''portador de luz'' (casa de verano abierta) o relacionarse con ''arrabal''. 2 Reyes 23:11 lo asocia con caballos dedicados al dios sol, que Josías removió. Crónicas lo menciona en el contexto de las divisiones de los porteros. Cualquiera que fuera su naturaleza precisa, representaba un área distinta que requería personal asignado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6504', 'spa', 'Dividir, separar, dispersar; separarse, ramificarse o causar división entre personas o cosas', 'Dividir, separar, dispersar; separarse, ramificarse o causar división entre personas o cosas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6505', 'spa', 'Mulo; el animal híbrido de monta usado como transporte real, bestia de carga y mercancía comercial en el antiguo Israel. Designa al mulo, el robusto h', 'Mulo; el animal híbrido de monta usado como transporte real, bestia de carga y mercancía comercial en el antiguo Israel. Designa al mulo, el robusto híbrido de caballo y burro apreciado en todo el antiguo Cercano Oriente por su fiabilidad en terrenos escabrosos. En las Escrituras, el mulo es llamativamente real: los hijos de Absalón montan mulos como marca de estatus principesco (2 Sam 13:29), y el propio Absalón queda fatalmente atrapado mientras cabalga uno en batalla (2 Sam 18:9). Salomón recibe mulos como tributo anual (1 Re 10:25), y Abdías busca pasto para los mulos reales durante la sequía (1 Re 18:5). Los mulos también aparecen como animales de carga (''la carga de un par de mulos'', 2 Re 5:17), en el comercio de Tiro (Ez 27:14) y entre el ganado de los exiliados que regresan (Esd 2:66). El Salmo 32:9 usa al mulo como imagen admonitoria de la terquedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6506', 'spa', 'mula, mula hembra (montada por la realeza)', 'Este término denota específicamente una mula hembra, apareciendo exclusivamente en 1 Reyes 1 durante la apresurada coronación de Salomón. Cuando Adonías intentó apoderarse del trono, David ordenó que Salomón montara ''mi mula'' hasta Gihón para la unción. Los tres versículos enfatizan esta mula real—la propia montura de David—significando la transferencia legítima de la realeza. Montar la mula del rey declaraba públicamente a Salomón como sucesor escogido. Aunque las mulas machos (pered) aparecen en otros lugares para varios usos, esta forma femenina destaca el animal específico que llevó a Salomón a su coronación, convirtiéndola en un símbolo viviente de continuidad dinástica y elección divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6507', 'spa', 'semillas, granos o simientes (posiblemente ''las separadas''), aparece en Joel 1:17 describiendo devastación agrícola', 'Este sustantivo poco frecuente, que aparece únicamente en Joel 1:17, significa semillas, granos o simientes. Su etimología sugiere ''cosas separadas'' o ''las dispersas'', refiriéndose posiblemente a semillas o granos individuales. La palabra aparece en la gráfica descripción de Joel sobre la sequía y la catástrofe agrícola, donde incluso la semilla almacenada se ha marchitado y podrido bajo los terrones. El contexto más amplio retrata un fracaso agrícola total: el grano marchito, las viñas secas, los árboles languídeos y los labradores consternados. Este término capta el nivel más básico de la esperanza agrícola —la semilla para la siembra del año siguiente— ahora destruida.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6508', 'spa', 'parque, huerto, jardín paradisíaco (préstamo persa)', 'Este préstamo persa (relacionado con ''paraíso'') denota un parque cerrado, huerto o reserva—típicamente fincas reales con árboles, frutos y belleza cultivada. Nehemías 2:8 solicita madera del ''bosque del rey''—probablemente una reserva forestal administrada. Eclesiastés 2:5 describe los extensos proyectos de construcción de Salomón: ''Hice huertos y parques'' plantados con árboles frutales. Cantar de los Cantares 4:13 lo usa metafóricamente: ''Tus renuevos son un paraíso de granados''—comparando a la amada con un jardín exuberante. El término entró en muchos idiomas (griego ''paradeisos,'' armenio, árabe) y eventualmente se asoció con el Edén y el paraíso celestial, aunque originalmente simplemente significaba un recinto cultivado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6509', 'spa', 'Fructificar, dar fruto; en Hifil, hacer fructífero -- verbo clave de bendición divina y promesa del pacto', 'Fructificar, dar fruto; en Hifil, hacer fructífero -- verbo clave de bendición divina y promesa del pacto');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6510', 'spa', 'Vaca, novilla -- hembra bovina; usada para ganado, simbolismo onírico, ritual sacrificial y metáfora profética', 'Vaca, novilla -- hembra bovina; usada para ganado, simbolismo onírico, ritual sacrificial y metáfora profética');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6511', 'spa', 'Pará, ciudad en el territorio de Benjamín mencionada en Josué 18:23', 'Este topónimo designa una ciudad asignada a la tribu de Benjamín durante la distribución territorial bajo Josué. Aparece únicamente en Josué 18:23, dentro de una lista de ciudades benjaminitas. Su ubicación exacta es incierta, aunque algunos la han vinculado con la moderna Khirbet el-Farah, al noreste de Anatot. El nombre פָּרָה es idéntico a la palabra hebrea común para «novilla» o «vaca», si bien se desconoce si esto refleja alguna característica del lugar o su etimología. El territorio de Benjamín, situado entre Judá y Efraín, incluía esta red de pequeñas ciudades en las tierras altas centrales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6512', 'spa', 'Topos (excavadores); posiblemente en Isaías 2:20, aunque el texto hebreo presenta dificultades textuales', 'Este término, que aparece solo en Isaías 2:20, es textualmente muy incierto. El hebreo tradicional lee «cavar» junto a «ratas», produciendo una construcción gramaticalmente problemática. Muchos eruditos enmiendan el texto para leer «a los topos» (לַחֲפַרְפָּרוֹת), entendiendo que los topos serían los animales que recibirían los ídolos desechados. El contexto describe a las personas arrojando sus ídolos de plata y oro «a los topos y a los murciélagos» en el día del juicio divino. Ambos animales representan lugares oscuros y despreciables donde terminarían los ídolos inútiles.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6515', 'spa', 'Parúa, padre de Josafat, gobernador provincial de Salomón en Isacar (1 Reyes 4:17)', 'Este nombre personal aparece únicamente en 1 Reyes 4:17, identificando al padre de Josafat, uno de los doce gobernadores provinciales de Salomón responsables de abastecer la casa real durante un mes al año. El hijo de Parúa administraba el territorio de Isacar. El nombre posiblemente deriva de una raíz que significa «florecer» o «brotar», aunque la etimología es incierta. Las traducciones griegas antiguas muestran considerable variación al transcribir este nombre. La nota genealógica establece legitimidad administrativa, pues la estructura gubernamental de Salomón requería funcionarios de confianza provenientes de familias establecidas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6516', 'spa', 'Parvaim, topónimo (ubicación incierta) asociado con oro de alta calidad en 2 Crónicas 3:6', 'Este nombre geográfico aparece únicamente en 2 Crónicas 3:6, designando la fuente del oro utilizado para revestir el templo de Salomón. La expresión «oro de Parvaim» sugiere un lugar renombrado por su oro de excelente calidad, aunque su identificación sigue siendo incierta. Algunos eruditos han propuesto ubicaciones en Arabia, posiblemente Farwa en Yemen o Sâq el-Farwain en la región del Néyed. El término aparece en la descripción detallada del Cronista sobre la construcción del templo, subrayando los materiales preciosos empleados. La mención de fuentes específicas de oro resalta la magnificencia del templo, usando los mejores materiales disponibles de tierras lejanas para la morada de Yahvé.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6517', 'spa', 'olla, vasija para cocinar (de barro o metal)', 'Este término designa una olla o vasija para cocinar, probablemente de barro pero posiblemente de metal, usada para hervir alimentos. Números 11:8 describe la preparación del maná moliéndolo y cocinándolo ''en la olla''. Jueces 6:19 tiene a Gedeón preparando carne y caldo para el ángel: ''el caldo lo puso en una olla''. 1 Samuel 2:14 describe la práctica corrupta en Silo donde el criado del sacerdote metía un tenedor ''en la sartén'' para reclamar carne de los sacrificios de los adoradores. El término enfatiza la función—una vasija para hervir—ya sea para sustento diario (maná), hospitalidad (Gedeón) o comidas sacrificiales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6519', 'spa', 'aldeas sin muros, asentamientos abiertos, poblados rurales', 'Este término describe asentamientos rurales sin murallas defensivas—aldeas o poblados abiertos en contraste con ciudades fortificadas. Ester 9:19 distingue a los judíos ''en las aldeas sin muros'' de aquellos en la ciudadela de Susa, celebrando Purim en días diferentes. Ezequiel 38:11 describe a Israel como ''tierra de aldeas sin muros''—asentamientos pacíficos e indefensos que Gog planea atacar. Zacarías 2:4 promete que Jerusalén será ''habitada como aldeas sin muros'' debido a la abundante población y protección divina. El término enfatiza vulnerabilidad (sin muros) pero también paz y expansión (sin necesidad de muros)—a veces bendición, a veces exposición al peligro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6521', 'spa', 'aldeano, habitante rural, asentamiento sin murallas (en contraste con la ciudad fortificada)', 'Este término designa a las personas que viven en aldeas sin murallas o en zonas rurales, en contraposición a las ciudades fortificadas. En Deuteronomio 3:5 se contrasta con ciudades amuralladas; en 1 Samuel 6:18, con ciudades fortificadas. La palabra aparece en Ester 9:19 para distinguir a los judíos rurales de los habitantes de la ciudad en su celebración del Purim. El énfasis recae en la ausencia de murallas defensivas, lo que hacía a estos asentamientos y sus habitantes más vulnerables y menos urbanizados que sus contrapartes citadinas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6522', 'spa', 'Ferezeo -- uno de los pueblos preisraelitas de Canaán, regularmente incluido entre las naciones a ser desposeídas', 'Ferezeo -- uno de los pueblos preisraelitas de Canaán, regularmente incluido entre las naciones a ser desposeídas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6523', 'spa', 'Hierro (el metal), usado en Daniel para la fuerza aplastante del cuarto reino y para cadenas e ídolos. El cognado arameo del hebreo barzel, que aparec', 'Hierro (el metal), usado en Daniel para la fuerza aplastante del cuarto reino y para cadenas e ídolos. El cognado arameo del hebreo barzel, que aparece exclusivamente en el libro de Daniel. El hierro domina la estatua del sueño de Nabucodonosor como material de las piernas y los pies (Dn 2:33-45), simbolizando el poder aplastante e inquebrantable del cuarto reino. Reaparece en la visión del gran árbol como la banda de hierro y bronce alrededor del tronco (Dn 4:12, 20), en los vasos del banquete de Belsasar (Dn 5:4, 23), y en los aterradores dientes de hierro de la cuarta bestia (Dn 7:7, 19). Cada ocurrencia conlleva connotaciones de fuerza imperial y dureza inflexible.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6524a', 'spa', 'Brotar, retoñar o florecer; en sentido figurado, prosperar o medrar; en Hifil, hacer florecer', 'Brotar, retoñar o florecer; en sentido figurado, prosperar o medrar; en Hifil, hacer florecer');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6524b', 'spa', 'Brotar o extenderse, usado exclusivamente de enfermedades cutáneas y forúnculos que erupcionan en el cuerpo en la legislación sacerdotal', 'Verbo (פָּרַח II) que significa brotar o extenderse, distinguido del homónimo פָּרַח I (''florecer, germinar'') por su asociación exclusiva con enfermedades. Las nueve ocurrencias describen la erupción de afecciones cutáneas en contextos ritual-legales: forúnculos que brotan sobre los egipcios durante la sexta plaga (Éx 9:9-10) y los patrones detallados de propagación de la צָרַעַת examinados por los sacerdotes en Levítico 13-14. El español ''brotar'' capta elegantemente tanto el sentido de germinar como el de erupcionar, revelando el vínculo conceptual entre una planta que rompe la tierra y una enfermedad que rompe la piel, conexión que probablemente une a ambos homónimos hebreos a nivel etimológico profundo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6525', 'spa', 'Flor, capullo, brote — floración botánica u ornamento en forma de capullo, usado literalmente de plantas y figuradamente de la gloria humana efímera. ', 'Flor, capullo, brote — floración botánica u ornamento en forma de capullo, usado literalmente de plantas y figuradamente de la gloria humana efímera. Un sustantivo que abarca desde el capullo cerrado hasta la flor abierta; פֶּרַח aparece en tres contextos vívidos. En las instrucciones del tabernáculo (Éx 25:31-34; 37:17-20), ornamentos en forma de flor de almendro adornan la menorá de oro — Nm 8:4 confirma que el candelabro fue hecho ''desde su base hasta sus flores''. La vara de Aarón milagrosamente ''produjo brotes, floreció y dio almendras maduras'' (Nm 17:23), validando su autoridad sacerdotal. En los profetas, la imagen se vuelve metafórica: Is 5:24 advierte que la ''flor'' de los malvados ''subirá como polvo'', mientras Nah 1:4 habla de la flor del Líbano marchitándose ante el poder de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6526', 'spa', 'Prole, chusma, turba; usado colectivamente en Job 30:12 para una multitud despreciable que acosa a Job', 'Este sustantivo colectivo aparece únicamente en Job 30:12, refiriéndose a una turba o chusma despreciable que se levanta contra Job. El término, que posiblemente significa «prole» o «cría» en sentido colectivo, conlleva connotaciones fuertemente negativas en su contexto. Job describe cómo marginados sociales — personas que él antes consideraba indignas de toda consideración — ahora se sienten con libertad de burlarse de él y maltratarlo. La palabra enfatiza la baja condición de sus atormentadores: no ciudadanos respetables sino una turba despreciable, la «prole» de los márgenes de la sociedad. Esto agrava la humillación en el lamento de Job: ha caído tan bajo que hasta la escoria social se atreve a hostigarlo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6527', 'spa', 'los que improvisan, cantan o rasguean descuidadamente; usado en Amós 6:5 criticando la música autocomplaciente', 'Esta rara forma verbal, que aparece únicamente en Amós 6:5, describe a quienes improvisan canciones o rasguean instrumentos musicales de manera frívola. La raíz puede significar ''dividir'', ''esparcir'' o ''separar'', produciendo traducciones como ''los que inventan cantos'' o ''los que improvisan''. El contexto es clave: Amós condena a los israelitas ricos que se recuestan en divanes lujosos, comen carne selecta, beben vino y se ungen con los mejores aceites, mientras ''improvisan al son del arpa''. La crítica no apunta a la música en sí, sino a la autoindulgencia frívola mientras la nación se desmorona. Inventan canciones como David, pero sin su devoción ni propósito.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6528', 'spa', 'uvas caídas, los granos que se desprenden durante la cosecha y deben dejarse para los pobres (Levítico 19:10)', 'Este sustantivo designa las uvas caídas o desprendidas, es decir, los granos individuales que caen al suelo durante la vendimia. Aparece únicamente en Levítico 19:10, dentro de la legislación que protege a los pobres y extranjeros. Se ordenaba a los israelitas no repasar sus viñedos ni recoger las uvas caídas, sino dejarlas para los miembros vulnerables de la comunidad. Esta es una de las varias leyes de espigueo que garantizaban que la eficiencia de la cosecha no eliminara el acceso al alimento de quienes carecían de tierra. El término literalmente significa ''lo desprendido'', enfatizando que son granos individuales separados del racimo, esparcidos por el suelo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6529', 'spa', 'Fruto, producto de árboles y tierra; metafóricamente, descendencia o resultado de las propias acciones.', 'Uno de los sustantivos más versátiles de la Biblia, פְּרִי abarca desde la cosecha literal de huertos y campos hasta el ''fruto'' metafórico del vientre, de la justicia y de los labios. En su uso más común aparece en cadenas constructas — ''fruto de la tierra'' (Nm 13:20), ''fruto del árbol'' (Gn 3:2) — catalogando la abundancia agrícola de la tierra prometida. La palabra adquiere profundidad teológica al extenderse a la descendencia (Sal 21:10, ''fruto del cuerpo'') y a las consecuencias morales (Pr 8:19; Is 3:10), una trayectoria que alcanza el Nuevo Testamento con el ''fruto del Espíritu''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6530', 'spa', 'Persona violenta, ladrón u opresor despiadado; usado para individuos sin ley y bestias rapaces', 'Describe a una persona o criatura caracterizada por la violencia, la ilegalidad y la agresión depredadora. En el Sal 17:4, David evita los caminos de los violentos; en Jer 7:11, el Templo se ha convertido en cueva de ladrones; Ezequiel usa el término para quienes profanan el espacio sagrado (7:22) y para un hijo derramador de sangre (18:10). Dan 11:14 habla de hombres violentos del pueblo que se levantan para cumplir una visión. Is 35:9 extiende la imagen a una bestia rapaz. La palabra evoca consistentemente una transgresión despiadada y agresiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6531', 'spa', 'Dureza, severidad, crueldad; siempre en la frase ''con dureza'' describiendo dominio opresivo o trabajo forzado', 'Sustantivo abstracto que aparece exclusivamente en la frase preposicional be-farekh (''con dureza''), describiendo el trato cruel de quienes están bajo autoridad. Egipto hizo trabajar a Israel con crueldad (Éx 1:13-14), y el Código de Santidad prohíbe tres veces gobernar a los compatriotas israelitas con severidad (Lv 25:43, 46, 53). Ez 34:4 extiende la acusación a los propios pastores de Israel que gobernaron al rebaño con dureza. La palabra funciona como barómetro moral del abuso de poder, una advertencia que resuena desde los campos de ladrillos del faraón hasta los fracasos del liderazgo israelita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6532', 'spa', 'Velo, cortina -- el cortinaje interior que separaba el Lugar Santo del Lugar Santísimo en el tabernáculo y el templo', 'Velo, cortina -- el cortinaje interior que separaba el Lugar Santo del Lugar Santísimo en el tabernáculo y el templo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6533', 'spa', 'rasgar, romper (vestiduras en duelo o prohibición sacerdotal)', 'Este verbo significa rasgar o romper vestiduras, apareciendo exclusivamente en las regulaciones sacerdotales de Levítico. Al sumo sacerdote se le prohíbe rasgar sus vestiduras incluso en duelo (Levítico 21:10), manteniendo pureza ritual y dignidad. Similarmente, se prohibió a Aarón y sus hijos romper sus ropas después de las muertes de Nadab y Abiú (Levítico 10:6), aunque el resto de Israel podía hacer duelo. Sin embargo, las ropas de un leproso debían estar rasgadas (Levítico 13:45) como parte de la identificación visible y separación. El verbo subraya la tensión entre respuestas naturales de dolor y requisitos de santidad sacerdotal—lo que la gente ordinaria hace para expresar duelo, los sacerdotes a veces deben abstenerse.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6534', 'spa', 'Parmasta, uno de los diez hijos de Amán ejecutados por los judíos en Susa (Ester 9:9)', 'Este nombre persa pertenece a uno de los diez hijos de Amán ejecutados por los judíos durante los eventos de Purim. El nombre aparece únicamente en Ester 9:9, en la lista de los hijos de Amán, todos muertos el día trece de Adar cuando los judíos se defendieron de sus enemigos. La etimología es incierta, aunque, al igual que otros nombres de la lista, parece ser auténticamente persa. Tras descubrirse la conspiración de Amán y su ejecución en la horca, Ester solicitó que sus diez hijos también fueran ejecutados y sus cuerpos exhibidos públicamente, tanto como justicia por el complot genocida de su padre como para disuadir futura violencia antisemita.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6535', 'spa', 'Parnac, padre de Elizafán de la tribu de Zabulón, involucrado en la división de la tierra (Números 34:25)', 'Este nombre propio aparece únicamente en Números 34:25, identificando al padre de Elizafán, el líder tribal elegido para representar a Zabulón en la distribución de la Tierra Prometida. Cuando Dios instruyó a Moisés que designara hombres para supervisar la repartición territorial de Canaán, cada tribu fue representada por un líder. El hijo de Parnac, Elizafán, cumplió ese rol por Zabulón. La etimología del nombre es incierta. Estos representantes tribales, trabajando junto a Josué y Eleazar el sumo sacerdote, debían asegurar la distribución justa y adecuada de la herencia territorial a cada tribu, un momento fundacional en el asentamiento de Israel en Canaán.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6536', 'spa', 'Dividir, hender (especialmente las pezuñas en la ley dietética); también partir o repartir (pan). Verbo cuyos dos temas verbales producen dos imágenes', 'Dividir, hender (especialmente las pezuñas en la ley dietética); también partir o repartir (pan). Verbo cuyos dos temas verbales producen dos imágenes distintas. En el Hifil aparece casi exclusivamente en Levítico 11 y Deuteronomio 14 para describir animales que ''dividen la pezuña'', criterio clave para los animales puros. En el Qal, el sentido se desplaza al acto de partir y repartir pan: Isaías 58:7 ordena ''partir tu pan con el hambriento'', y Jeremías 16:7 describe a los dolientes partiendo pan juntos. La acción física de hender es la misma, pero el contexto la transforma de una regulación de pureza en una ética de generosidad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6537a', 'spa', 'ha sido dividido (forma pasiva aramea), aparece en Daniel 5:28 en la interpretación de ''MENE MENE TEKEL UFARSIN''', 'Esta forma verbal pasiva aramea significa ''ha sido dividido'' o ''ha sido partido en dos'', de la raíz פְּרַס (cognada del hebreo פָּרַס). Aparece en Daniel 5:28 como parte de la interpretación que Daniel hace de la escritura misteriosa en la pared del palacio de Belsasar. La palabra juega con ''PERES'' (una de las palabras escritas) y ''Persia'', produciendo un doble sentido: ''Tu reino ha sido dividido y entregado a los medos y los persas.'' Este es el clímax del mensaje divino, tras MENE (contado) y TEKEL (pesado). Esa misma noche, la profecía se cumplió cuando Darío el Medo conquistó Babilonia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6539', 'spa', 'Persia (Paras) -- el antiguo imperio al este de Babilonia, prominente en la literatura bíblica postexílica', 'Persia (Paras) -- el antiguo imperio al este de Babilonia, prominente en la literatura bíblica postexílica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6540', 'spa', 'Persia / los persas; el imperio y su pueblo, especialmente en Daniel y Esdras junto con Media', 'El nombre propio Paras en sus apariciones arameas, designando el Imperio Persa y su pueblo. En Daniel, Persia aparece en la fatídica escritura en la pared: ''tu reino ha sido dividido y entregado a los medos y persas'' (Dan 5:28), y en la frase legal compuesta ''la ley de medos y persas'' (Dan 6:8, 12, 15). En Esdras, marca la autoridad imperial persa bajo la cual se reconstruyó el Templo (Esd 4:24; 6:14). El nombre evoca consistentemente el segundo gran imperio en la secuencia bíblica del orden mundial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6541', 'spa', 'Pezuña de un animal, especialmente la pezuña hendida que distingue a los animales limpios de los inmundos en la ley levítica. Se refiere a la cubierta', 'Pezuña de un animal, especialmente la pezuña hendida que distingue a los animales limpios de los inmundos en la ley levítica. Se refiere a la cubierta dura del pie de un ungulado, ya sea hendida o sólida. En la legislación dietética de la Torá, la pezuña hendida (parsah) es una de las dos marcas definitorias de un animal ritualmente limpio (Lv 11:3; Dt 14:6). La misma palabra se aplica a las pezuñas no divididas de los caballos (Is 5:28; Jer 47:3). Figuradamente, Mi 4:13 visualiza las pezuñas de Sion hechas de bronce, aplastando a las naciones — una imagen vívida del juicio con poder divino.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6542', 'spa', 'el persa, designación gentilicia que aparece con artículo definido en Nehemías 12:22', 'Este adjetivo gentilicio significa «persa», refiriéndose a alguien procedente de Persia. En Nehemías 12:22 aparece con artículo definido, «el persa», aludiendo a un rey persa específico durante cuyo reinado se registraron las genealogías levíticas. La referencia es probablemente a Darío II (423-404 a.C.) o a Darío III (336-331 a.C.), aunque las opiniones académicas varían. La mención indica que los registros oficiales de las familias sacerdotales se mantuvieron durante el dominio persa, evidenciando continuidad administrativa. Estos registros genealógicos eran esenciales para establecer la descendencia sacerdotal legítima para el servicio del templo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6544a', 'spa', 'cuando se soltaron, cuando el cabello se desata, o cuando los líderes guiaron (incierto); aparece en Jueces 5:2', 'Este infinitivo constructo aparece al inicio del cántico de Débora (Jueces 5:2), pero su significado preciso es debatido. Las interpretaciones tradicionales incluyen «cuando los líderes guiaron en Israel» o «cuando los hombres dejaron suelto su cabello», posiblemente indicando dedicación a la guerra o un voto. La raíz פָּרַע abarca significados de soltar, desatar o dirigir. Las traducciones modernas varían ampliamente: algunas enfatizan el liderazgo, otras la dedicación guerrera, y otras traducen más literalmente sobre el cabello suelto. La frase introduce la alabanza por la respuesta de Israel ante la crisis.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6544b', 'spa', 'Soltar, descubrir, descuidar o dejar sin freno; en Hifil, causar cesación o desorden. Verbo de liberación y exposición: en su tema Qal, פָּרַע evoca c', 'Soltar, descubrir, descuidar o dejar sin freno; en Hifil, causar cesación o desorden. Verbo de liberación y exposición: en su tema Qal, פָּרַע evoca cabello suelto, restricciones removidas y consejo desechado. Cuando Aarón dejó suelto a Israel en el Sinaí (Éx 32:25), la misma raíz describe tanto la causa como el resultado visible: un pueblo ''desenfrenado'' (participio pasivo). Proverbios advierte repetidamente contra ''rechazar'' la disciplina (Pr 13:18; 15:32). El Hifil intensifica la imagen: Faraón acusa a Moisés de hacer que el pueblo ''cese'' en su trabajo (Éx 5:4), y la corrupción de Acaz provocó que Judá ''se desenfrenara'' (2 Cr 28:19).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6547', 'spa', 'Faraón; título de los reyes de Egipto, del egipcio pr-ꜥꜣ (''casa grande'').', 'Derivado del egipcio pr-ꜥꜣ que significa ''casa grande'', Faraón aparece 268 veces como título real de los reyes de Egipto. Funciona como nombre propio a lo largo de toda la Biblia hebrea, abarcando las narraciones de la estancia de Abraham (Gn 12:15-18), el ascenso de José al poder, la confrontación del Éxodo con Moisés, la alianza diplomática de Salomón (1 R 3:1) y los oráculos proféticos posteriores contra Egipto (Ez 29-31). El título lleva un peso narrativo inmenso como el soberano extranjero arquetípico a quien Dios humilla. Todas las traducciones preservan el préstamo lingüístico prácticamente sin cambios: español Faraón, francés Pharaon, alemán Pharao.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6549', 'spa', 'Faraón Necao (II); el rey egipcio que mató a Josías e instaló a Joacim en el trono de Judá', 'Nombre propio del faraón Necao II, gobernante de la dinastía XXVI de Egipto (r. 610-595 a.C.), quien aparece en un momento decisivo de la historia de Judá. Marchando hacia el norte para auxiliar a Asiria contra Babilonia, Necao mató al rey Josías en Meguido (2 R 23:29), impuso tributo a Judá, depuso al hijo de Josías, Joacaz, e instaló a Joacim como rey vasallo (2 R 23:33-35). Posteriormente fue derrotado por Nabucodonosor en Carquemis (Jer 46:2). El relato del Cronista añade que Necao afirmó tener autorización divina para su campaña (2 Cr 35:20-22). Todas las traducciones transliteran el nombre de diversas formas: Neco, Necao, Neko.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6551', 'spa', 'Paros — ''pulga''; cabeza de una numerosa familia postexílica que regresó de Babilonia', 'Nombre propio que significa ''pulga'', identificando al ancestro de una de las familias más grandes de la comunidad postexílica. Los hijos de Paros sumaban 2.172 en un censo (Esd 2:3) y 2.818 en otro (Neh 7:8), lo que los convertía en uno de los clanes más prominentes entre los que regresaron. Aparecen miembros en la caravana de Esdras (Esd 8:3), entre quienes habían tomado esposas extranjeras (Esd 10:25) y en el proyecto de reconstrucción de la muralla bajo Nehemías (Neh 3:25). Un Paros también selló la renovación del pacto (Neh 10:14). Pese a su humilde etimología, esta familia desempeñó un papel destacado en la restauración de Judá tras el exilio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6552', 'spa', 'en Piratón, ciudad en la región montañosa de Efraín mencionada en Jueces 12:15', 'Este topónimo designa una ciudad en la región montañosa de Efraín donde fue sepultado el juez Abdón. Aparece en Jueces 12:15 identificando la ciudad natal y el lugar de sepultura de Abdón. El nombre posiblemente significa «altura» o se relaciona con una raíz que significa «elevar». La ciudad ha sido identificada con la actual Far''ata, a unos diez kilómetros al oeste-suroeste de Nablus (la antigua Siquem). La zona también fue hogar de Benaía hijo de Joiada, uno de los valientes de David, conocido como «Benaía el piratonita». Esta ciudad efraimita aparece tanto en el período de los jueces como en la era de David, manteniendo su importancia a lo largo de la historia temprana de Israel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6553', 'spa', 'Piratonita — gentilicio de Piratón, ciudad en la serranía de Efraín', 'Adjetivo gentilicio que identifica a alguien procedente de Piratón, localidad en la zona montañosa de Efraín. Se aplica a dos personajes: Abdón hijo de Hilel, que juzgó a Israel y fue sepultado en Piratón (Jue 12:13, 15), y Benaía, uno de los guerreros de élite de David y comandante de una división mensual (2 Sam 23:30; 1 Cr 11:31; 27:14). La leve variación ortográfica entre las formas de Samuel y Crónicas refleja la fluidez escribal habitual del texto hebreo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6554', 'spa', 'Farfar, río cerca de Damasco mencionado junto al Abaná en 2 Reyes 5:12', 'Este es el nombre de un río que fluye cerca de Damasco, mencionado únicamente en 2 Reyes 5:12 en la respuesta indignada de Naamán a la instrucción de Eliseo de lavarse en el Jordán. Naamán protestó: «¿No son el Abaná y el Farfar, ríos de Damasco, mejores que todas las aguas de Israel?» El Farfar es probablemente el moderno río Awaj, que fluye al sur de Damasco. Junto con el Abaná (probablemente el Barada), abastecía de agua a Damasco y su oasis circundante, haciéndola una de las ciudades más hermosas del mundo antiguo. El argumento de Naamán era que Damasco disponía de fuentes de agua abundantes y superiores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6555', 'spa', 'Verbo de fuerza bruta e irresistible; פָּרַץ evoca la imagen de algo — o alguien — que rompe barreras que no pueden contener. Cuando Pérez irrumpe del', 'Verbo de fuerza bruta e irresistible; פָּרַץ evoca la imagen de algo — o alguien — que rompe barreras que no pueden contener. Cuando Pérez irrumpe del vientre (Gn 38:29), su propio nombre se convierte en la ilustración más vívida de esta palabra: ''¡Te has abierto brecha!'' La misma energía explosiva reaparece cuando Dios ''irrumpe'' contra Uza en la era (2 S 6:8) y cuando Israel ''se extiende'' al oeste, este, norte y sur en el sueño de Jacob (Gn 28:14). El español distingue el sentido destructivo (derribar) del expansivo (extender), mientras que el sentido de ''instar, insistir'' en 1 S 28:23 se traduce como insistir, revelando tres marcos semánticos genuinamente distintos que el verbo hebreo une bajo una sola raíz.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6556', 'spa', 'Brecha, abertura; irrupción, estallido violento — una rotura en un muro o barrera, o un rompimiento enérgico. El sustantivo פֶּרֶץ abarca tanto el res', 'Brecha, abertura; irrupción, estallido violento — una rotura en un muro o barrera, o un rompimiento enérgico. El sustantivo פֶּרֶץ abarca tanto el resultado estático como el evento dinámico de traspasar un límite. Con mayor frecuencia se refiere a una brecha o abertura en un muro — el tipo de daño en fortificaciones que requiere reparación urgente, como cuando Nehemías trabajó para cerrar las brechas en los muros de Jerusalén (Neh 6:1) o cuando Ezequiel desafió a los falsos profetas que no ''subieron a las brechas'' (Ez 13:5; 22:30). Figuradamente, Dios abrió una brecha entre los israelitas por no guardar el orden prescrito (Jue 21:15; Sal 106:23). En un sentido más dinámico, la palabra describe una irrupción o estallido violento, como cuando David nombró Baal-perazim (''Señor de las irrupciones'') después de que Dios irrumpió contra sus enemigos como aguas desbordadas (2 S 5:20; 1 Cr 14:11).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6557', 'spa', 'Pérets (Fares), hijo de Judá y Tamar; antepasado de David y de la línea mesiánica. Pérets, cuyo nombre significa ''brecha'' por el dramático momento en ', 'Pérets (Fares), hijo de Judá y Tamar; antepasado de David y de la línea mesiánica. Pérets, cuyo nombre significa ''brecha'' por el dramático momento en que irrumpió delante de su gemelo Zéraj al nacer (Gn 38:29), se convirtió en cabeza de un importante clan judío. De su línea descienden Hesrón, Ram y finalmente David (Rt 4:12, 18–22; 1 Cr 2:4–5). Los peresitas forman una de las principales divisiones tribales de Judá (Nm 26:20–21), y la Jerusalén posexílica fue poblada en gran medida por sus descendientes (1 Cr 9:4; Neh 11:4, 6). La genealogía de Rut traza explícitamente el linaje real desde Pérets hasta David, haciendo de este nombre un marcador teológico del propósito soberano de Dios obrando a través de una unión inesperada. El griego Φαρές y el español ''Fares'' preservan la forma septuagintal familiar de la genealogía de Cristo en Mateo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6558', 'spa', 'el faresita, designación gentilicia para los descendientes de Fares, hijo de Judá (Números 26:20)', 'Este adjetivo gentilicio, que aparece con artículo definido como sustantivo colectivo, designa al clan descendiente de Fares, uno de los hijos gemelos de Judá nacidos de Tamar. En Números 26:20 aparece en el censo del desierto que enumera los clanes de Judá. Los faresitas llegaron a ser una de las familias más destacadas de Judá: el rey David descendía de esta línea a través de Booz y Rut. La importancia del clan se refleja en la bendición dada a Booz en su boda con Rut: «Sea tu casa como la casa de Fares, a quien Tamar dio a luz a Judá» (Rut 4:12). Los faresitas constituían una subdivisión principal de la tribu de Judá.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6559', 'spa', 'Perazim, lugar montañoso asociado con el juicio divino en Isaías 28:21', 'Este topónimo aparece en Isaías 28:21 como «monte Perazim», evocando un lugar donde Dios intervino previamente en batalla. El nombre significa «brechas» o «irrupciones», en referencia a Baal-perazim, donde David derrotó a los filisteos (2 Samuel 5:20). Allí David declaró que el SEÑOR había irrumpido contra sus enemigos como un torrente desbordado. Isaías invoca esta memoria con ironía: así como Dios luchó a favor de Israel, ahora se levantará para ejecutar su «obra extraña» contra su propio pueblo. La referencia geográfica subraya la inversión: la bendición del pacto se convierte en maldición.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6560', 'spa', 'Peres (hijo de Judá y Tamar); también topónimos que evocan ''brecha'' o ''ruptura''', 'Nombre propio que designa principalmente al hijo de Judá y Tamar, cuyo nacimiento implicó ''abrirse paso'' antes que su gemelo Zéraj (Génesis 38:29). El nombre adquirió gran importancia en la genealogía de Judá, apareciendo en Crónicas, Rut y Nehemías. También designa dos lugares: Peres-uza (''brecha de Uza''), cerca de Jerusalén, donde Dios hirió a Uza por tocar el arca (2 Samuel 6:8; 1 Crónicas 13:11), y posiblemente el monte Perazim (Isaías 28:21). El nombre evoca la idea de irrumpir, abrirse paso o abrir brecha.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6561', 'spa', 'Arrancar, desgarrar o rescatar; abarca desde quitar ornamentos hasta despedazar presas y librar de enemigos', 'Verbo cuyo núcleo físico es el movimiento violento de arrancar. En Génesis 27:40, Isaac dice a Esaú que ''arrancará'' el yugo de su cuello, y en Éxodo 32:2-3 los pendientes de oro son arrancados para el becerro. La misma imagen enérgica se extiende a un león que despedaza su presa (Sal 7:2; Nah 2:13) y a ramas desgajadas de una vid (Ez 19:12). Notablemente, los cognados arameos y siríacos orientan la palabra hacia ''rescatar'' y ''redimir'', y este hilo semántico aflora en el Salmo 136:24 y Lamentaciones 5:8, donde Dios arranca a su pueblo de las manos de sus opresores.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6562', 'spa', 'Romper, arrancar (imperativo arameo); aparece en Daniel 4:27 sobre apartarse del pecado', 'Es una forma imperativa aramea que significa «¡rompe!» o «¡arráncate!», de una raíz afín al hebreo פָּרַק (arrancar, desgarrar). Aparece en Daniel 4:27, en el consejo de Daniel a Nabucodonosor tras interpretar su sueño perturbador. Daniel exhorta al rey: «Redime tus pecados con justicia y tus iniquidades con misericordia hacia los oprimidos». El verbo transmite la idea de separarse violentamente de algo, arrancarse del mal. Aquí introduce una exhortación moral urgente: quizá el terrible cumplimiento del sueño podría evitarse si el rey cambiaba radicalmente su conducta. El término enfatiza una ruptura moral decisiva, no una reforma gradual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6564', 'spa', 'Fragmento, caldo (lectura Ketiv en Isaías 65:4); el consenso académico lee «caldo» (מְרַק) en su lugar', 'Esta palabra aparece en el Ketiv (texto escrito) de Isaías 65:4, pero se considera ampliamente una corrupción textual. La frase literalmente dice «y fragmento de abominaciones en sus vasijas», lo cual tiene poco sentido. El Qeré (lectura oral) y la mayoría de las traducciones modernas siguen la enmienda a מְרַק (maraq), que significa «caldo», produciendo «caldo de cosas abominables en sus vasijas». El contexto describe prácticas religiosas sincretistas: sentarse en tumbas, pasar noches en lugares secretos, comer carne de cerdo. La referencia al caldo de animales impuros encaja en este catálogo de transgresiones.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6565a', 'spa', 'Quebrantar, anular, frustrar; Hifil: violar un pacto, invalidar un voto, desbaratar un consejo; Hofal: ser quebrantado, quedar en nada', 'Quebrantar, anular, frustrar; Hifil: violar un pacto, invalidar un voto, desbaratar un consejo; Hofal: ser quebrantado, quedar en nada');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6565b', 'spa', 'partir, dividir, agrietar (la tierra o el mar)', 'Este verbo, posiblemente relacionado o idéntico con la raíz que significa ''quebrar/frustrar'', describe división o partición física. Salmo 74:13 celebra el poder de Dios: ''Dividiste el mar con tu poder''—probablemente recordando la liberación del Éxodo a través del Mar Rojo. Isaías 24:19 usa formas intensivas para describir catástrofe cósmica: ''La tierra se parte, se agrieta completamente''—totalmente destrozada en juicio divino. Ambos contextos involucran división dramática y contundente—ya sea redentora (partir las aguas para Israel) o destructiva (la tierra quebrantándose). El verbo transmite separación o fractura violenta, poderes desatados solo por acción divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6566', 'spa', 'פָּרַשׂ es el verbo principal de la Biblia hebrea para el gesto de abrir ampliamente y extender hacia afuera: manos alzadas en oración, alas desplegad', 'פָּרַשׂ es el verbo principal de la Biblia hebrea para el gesto de abrir ampliamente y extender hacia afuera: manos alzadas en oración, alas desplegadas en vuelo o protección, prendas tendidas, redes lanzadas. Capta una acción visual y espacial bien definida: la imagen de Salomón extendiendo sus manos hacia el cielo en la dedicación del templo (1 R 8:22), los querubines desplegando sus alas sobre el arca (1 R 8:7), o la adúltera tendiendo una cubierta sobre su lecho (Pr 7:16). El Piel intensifica la acción y, en algunos casos llamativos, desplaza el significado hacia esparcir o dispersar personas — una extensión metafórica donde lo que se ''extiende'' es una población en lugar de un objeto físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6567a', 'spa', 'Hacer distinto, declarar con claridad, explicar; separar o distinguir', 'Verbo que significa hacer algo claro y preciso, declarar o explicar con exactitud. En Levítico 24:12 describe la espera de que Dios manifestara su voluntad de manera inequívoca. Números 15:34 presenta una situación similar, aguardando una declaración clara del juicio divino. Nehemías 8:8 emplea el participio para describir cómo los levitas leyeron la Ley ''con claridad'' (o ''con interpretación''), haciéndola inteligible al pueblo. El raro participio nifal en Ezequiel 34:12 es textualmente incierto, pero podría relacionarse con ovejas dispersas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6567b', 'spa', 'Picar, punzar (forma Hifil); usado metafóricamente del efecto del vino en Proverbios 23:32', 'Este verbo poco frecuente significa «picar» o «punzar», y aparece únicamente en Proverbios 23:32 como advertencia sobre el vino. La raíz posiblemente se relaciona con palabras que designan aguijón o vara punzante. En la línea culminante del proverbio, se advierte que el vino que reluce atractivamente y se desliza suavemente «al final muerde como serpiente y pica como víbora». Los verbos paralelos (morder y picar) describen ataques de serpientes venenosas, enfatizando el peligro engañoso del vino. Parece agradable al principio pero acarrea consecuencias ponzoñosas: adicción, pobreza, conflictos y daño físico.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6568', 'spa', 'Claramente, hecho distinto (participio pasivo arameo); aparece en Esdras 4:18 sobre una carta traducida', 'Es un participio pasivo arameo que significa «hecho claro» o «hecho distinto», de una raíz que significa separar, distinguir o interpretar. Aparece en Esdras 4:18 en la respuesta del rey Artajerjes a la acusación contra los judíos que reconstruían Jerusalén. El rey escribe: «La carta que nos enviasteis ha sido leída claramente ante mí». El término indica que la carta aramea fue presentada con claridad al rey persa, posiblemente traducida al persa o simplemente leída en voz alta con esmero. La misma raíz describe más adelante la práctica de los levitas de hacer las Escrituras comprensibles al pueblo (Nehemías 8:8).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6569', 'spa', 'Estiércol, excremento, contenido intestinal; desecho del animal sacrificial que debe quemarse fuera del campamento.', 'Sustantivo masculino פֶּרֶשׁ que designa el contenido intestinal y el estiércol de un animal sacrificial — el desecho que debe ser llevado fuera del campamento y quemado. Aparece exclusivamente en la legislación ritual del Pentateuco: la ofrenda de consagración (Éx 29:14), la ofrenda por el pecado (Lv 4:11; 8:17; 16:27) y la ceremonia de la vaca alazana (Nm 19:5). En la impactante reprensión profética de Malaquías, Dios amenaza con esparcir el estiércol de las fiestas sobre los rostros de los sacerdotes negligentes (Mal 2:3), subrayando la gravedad de la impureza ritual.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6570', 'spa', 'Peres, nombre propio manasita que aparece en la genealogía de 1 Crónicas 7:16', 'Este nombre propio aparece únicamente en 1 Crónicas 7:16, dentro de los registros genealógicos de los descendientes de Manasés. Peres fue hijo de Maaca, esposa de Maquir, lo que lo sitúa dentro del clan manasita de Galaad. El nombre posiblemente se relaciona con raíces que significan «separar» o «distinguir», aunque su etimología es incierta. Las genealogías del Cronista, aunque a veces selectivas y esquemáticas, preservan la memoria tribal y establecen vínculos familiares esenciales para mantener la identidad tribal durante y después del exilio. Peres representa una rama de la poderosa tribu de Manasés que se asentó al este del Jordán, en Galaad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6571a', 'spa', 'Caballo, corcel; caballos de guerra o caballería montada, sinónimo menos frecuente de סוּס', 'Sustantivo que designa al caballo o corcel, funcionando como sinónimo menos frecuente del común סוּס. Aparece en contextos militares y comerciales: corceles negociados desde Togarmá junto con caballos y mulos (Ez 27:14), caballería que un rey reclutará (1 Sam 8:11), caballos cuya velocidad se compara con un ejército de langostas (Jl 2:4) y jinetes en formación de combate (Jer 46:4; Is 28:28). La raíz posee cognados en árabe, etiópico y sabeo, todos con el significado de caballo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6571b', 'spa', 'Sustantivo masculino que designa a un soldado montado, que aparece casi siempre en plural (parashim) junto a רֶכֶב (''carros de guerra'') en descripcion', 'Sustantivo masculino que designa a un soldado montado, que aparece casi siempre en plural (parashim) junto a רֶכֶב (''carros de guerra'') en descripciones de fuerzas militares del antiguo Cercano Oriente. La caballería egipcia escolta la procesión fúnebre de Jacob (Gn 50:9), y los jinetes del faraón persiguen a Israel a través del mar Rojo (Éx 14:9, 17-28; 15:19). La palabra reaparece para la caballería filistea (1 S 13:5), tropas montadas arameas (2 S 8:4; 10:18) y los ejércitos de Asiria y Babilonia. Nahúm 3:3 pinta un cuadro aterrador del ''jinete que carga'' con espada reluciente. El cognado árabe fāris y el etiópico faras confirman el vínculo pansemítico entre esta raíz y la equitación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6572a', 'spa', 'Copia, transcripción (préstamo del persa); aparece en Esdras 7:11 refiriéndose a la copia de un documento', 'Este sustantivo significa «copia» o «transcripción» y es un préstamo del persa incorporado al hebreo a través del arameo. Aparece únicamente en Esdras 7:11, donde introduce la carta de Artajerjes que autorizaba la misión de Esdras: «Esta es la copia de la carta que el rey Artajerjes dio al sacerdote y escriba Esdras.» El término indica que se trata de una transcripción del decreto original, conservada en las memorias de Esdras. La adopción de vocabulario administrativo persa refleja la realidad de la vida judía bajo el dominio persa, donde los documentos oficiales empleaban la terminología imperial. Una variante de la misma palabra aparece en otros pasajes de Esdras y Ester.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6572b', 'spa', 'copia (de documento escrito o decreto)', 'Este préstamo persa significa ''copia'' de un documento, apareciendo exclusivamente en Ester respecto a edictos reales. Ester 3:14 ordena que ''una copia del edicto'' autorizando la destrucción judía sea publicada en todas las provincias. Ester 4:8 tiene a Mardoqueo dando a Ester ''una copia del decreto escrito'' para que vea la amenaza. Ester 8:13 similarmente manda publicar ''una copia del edicto'' permitiendo autodefensa judía. El término indica duplicados oficiales distribuidos a través del vasto Imperio Persa para asegurar implementación uniforme de mandatos reales. La palabra es esencialmente idéntica a ''parsegen'' (otra forma del mismo préstamo), ambas significando copia autorizada.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6573', 'spa', 'copia (de documento escrito o carta)', 'Este préstamo arameo (variante de ''patsegen'') significa ''copia'' de documento oficial, apareciendo en Esdras respecto a correspondencia con autoridades persas. Esdras 4:11 introduce ''esta es una copia de la carta'' que los acusadores enviaron a Artajerjes oponiéndose a la reconstrucción de Jerusalén. El versículo 23 comienza: ''cuando fue leída la copia de la carta del rey Artajerjes,'' provocando acción para detener la construcción. Esdras 5:6 presenta ''la copia de la carta'' que Tatnai envió preguntando sobre la autorización de reconstrucción. El término indica duplicados oficiales de correspondencia imperial—copias circuladas a partes relevantes mientras originales permanecían en archivos reales. La palabra refleja prácticas administrativas persas adoptadas en todo el imperio.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6574', 'spa', 'Excremento, inmundicia (posiblemente); palabra textualmente incierta en Jueces 3:22', 'Este hápax legómenon (palabra que aparece una sola vez) en Jueces 3:22 es textual y etimológicamente incierto. El contexto es gráfico: tras clavar Ehúd su daga en el obeso rey Eglón, «salió el excremento» (o posiblemente «la hoja salió por detrás»). Muchos eruditos proponen enmendar el texto a פֶּרֶשׁ, que significa «estiércol» o «heces», un detalle realista aunque desagradable de una puñalada abdominal. La Vulgata y el Targum apoyan esta lectura. La incertidumbre refleja tanto el pudor escribal, que pudo generar eufemismos o corrupción textual, como lo inusual del vocabulario. En cualquier caso, la narrativa subraya la cruda realidad física del asesinato.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6576', 'spa', 'Extender, desplegar (infinitivo absoluto Piel, posiblemente problemático); aparece en Job 26:9 sobre Dios extendiendo nubes', 'Esta forma de infinitivo absoluto aparece únicamente en Job 26:9, aunque su estatus textual es discutido. La frase dice literalmente «extendiendo sobre ella su nube», refiriéndose a Dios que oscurece la faz de la luna llena desplegando nubes sobre ella. La forma es inusual (infinitivo absoluto Piel), lo que lleva a algunos eruditos a proponer una enmienda a participio. Sin embargo, el infinitivo absoluto puede funcionar como verbo finito o sustantivo verbal en la poesía hebrea. La imagen retrata el dominio soberano de Dios sobre los fenómenos celestes: Él vela incluso el brillo de la luna a voluntad, desplegando sus nubes. Esto encaja con el tema central de Job 26 sobre el poder incomprensible de Dios sobre la creación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6577', 'spa', 'Parsandata, uno de los diez hijos de Amán ejecutados durante los eventos de Purim (Ester 9:7)', 'Este nombre persa pertenece a uno de los diez hijos de Amán que fueron ejecutados por los judíos en Susa durante los acontecimientos conmemorados en la fiesta de Purim. Parsandata aparece primero en la lista de hermanos en Ester 9:7. Como los demás nombres de esta lista, tiene forma auténticamente persa, aunque su etimología precisa es incierta. Después de que la reina Ester revelara el complot genocida de Amán y este fuera ejecutado, Ester solicitó permiso para eliminar también a sus hijos, tanto como justicia por su complicidad como para prevenir futuras venganzas. Los diez fueron muertos el día trece de Adar y sus cuerpos exhibidos públicamente en Susa.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6578', 'spa', 'Éufrates — el gran río de Asia occidental, uno de los cuatro ríos del Edén y la frontera norte ideal de Israel. El sustantivo propio hebreo Perat, que', 'Éufrates — el gran río de Asia occidental, uno de los cuatro ríos del Edén y la frontera norte ideal de Israel. El sustantivo propio hebreo Perat, que designa el Éufrates, el mayor río de Asia occidental. Aparece por primera vez como uno de los cuatro ríos del Edén (Gn 2:14) y luego como la frontera norte de la tierra prometida a Abraham (Gn 15:18). A lo largo de la historia deuteronomista y los profetas, ''el gran río, el río Éufrates'' marca la extensión ideal del territorio israelita (Dt 1:7; 11:24; Jos 1:4). Jeremías usa el Éufrates simbólicamente — ordenando enterrar un cinto de lino allí (Jer 13:4-7) — e históricamente, como el sitio de la decisiva batalla de Carquemis (Jer 46:2, 6, 10). La forma asiria Purattu subyace al nombre hebreo, pasando por el persa antiguo Ufratu al griego Euphrates.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6579', 'spa', 'nobles, altos funcionarios, aristócratas (término persa)', 'Este préstamo del persa denota nobles o funcionarios de alto rango, la élite aristocrática del imperio. Ester 1:3 describe el gran banquete de Asuero para ''sus nobles y funcionarios''—la estructura de poder del imperio en exhibición. Ester 6:9 ordena que Mardoqueo sea honrado: ''que la vestidura y el caballo sean entregados a uno de los funcionarios más nobles del rey''—alguien de rango suficiente para dirigir la procesión. Daniel 1:3 registra que Nabucodonosor ordenó traer ''algunos de los israelitas de la familia real y de la nobleza''—seleccionando cautivos de élite para el entrenamiento en la corte babilónica. El término indica consistentemente el estrato social más alto, aquellos más cercanos al poder real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6580', 'spa', 'transgresión o posiblemente insensatez (textualmente incierto); aparece en Job 35:15 en un pasaje difícil', 'Este hápax legómenon en Job 35:15 presenta serios problemas textuales. El versículo en el Texto Masorético resulta difícil de traducir de forma coherente. La mayoría de las traducciones modernas siguen las versiones antiguas (Septuaginta, Teodocio, Símaco, Vulgata) y enmiendan esta palabra a פֶּשַׁע, que significa ''transgresión'' o ''rebelión''. La lectura enmendada produce algo como: ''Y ahora, porque su ira no castiga, y él no presta gran atención a la transgresión''. Esto encaja en el discurso de Elihú, quien argumenta que el aparente silencio de Dios no implica que ignore el pecado. La incertidumbre textual refleja una posible corrupción temprana o un término extremadamente raro.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6581', 'spa', 'Extenderse (de una enfermedad cutánea); término técnico sacerdotal usado exclusivamente en Levítico 13-14 para la inspección diagnóstica', 'Extenderse (de una enfermedad cutánea); término técnico sacerdotal usado exclusivamente en Levítico 13-14 para la inspección diagnóstica');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6582', 'spa', 'despedazar, desgarrar en pedazos (forma Piel); usado en Lamentaciones 3:11 donde Dios trata al hablante como presa', 'Este verbo en la conjugación Piel significa ''despedazar'' o ''desgarrar violentamente'', y aparece únicamente en Lamentaciones 3:11. El hablante emplea imágenes de depredador para describir su sufrimiento: ''Torció mis caminos y me despedazó; me dejó desolado''. El verbo sigue la imagen de Dios como león u oso que acecha para atacar (versículo 10). El lenguaje de desgarro es visceral y violento: no se trata de un simple ataque, sino de un destrozo total. Esto refleja la cruda honestidad de Lamentaciones sobre el sufrimiento, donde el poeta no suaviza la acción divina sino que atribuye directamente la catástrofe a Dios, aun manteniendo la fe en que sus misericordias nunca cesan.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6583', 'spa', 'Pasjur; nombre sacerdotal llevado por varios individuos, incluyendo el perseguidor de Jeremías y jefes de clanes posexílicos. Nombre personal que apar', 'Pasjur; nombre sacerdotal llevado por varios individuos, incluyendo el perseguidor de Jeremías y jefes de clanes posexílicos. Nombre personal que aparece a lo largo de varios siglos de la historia israelita. El portador más notable es Pasjur hijo de Imer, el oficial principal del templo que golpeó y encarceló a Jeremías, solo para recibir el devastador renombramiento profético ''Magor-misabib'' — Terror por todas partes (Jer 20:1–6). Un segundo Pasjur, hijo de Malquías, aparece entre los oficiales que arrojaron a Jeremías a una cisterna (Jer 38:1). El nombre también designa a una familia sacerdotal que regresó de Babilonia (Esd 2:38; Neh 7:41) y cuyos miembros se habían casado con mujeres extranjeras (Esd 10:22). El griego traduce el nombre como Πασχωρ.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6584', 'spa', 'Despojar de vestiduras, desollar un animal o hacer una incursión repentina; abarca desvestirse, despojo forzado, desuello y asalto militar', 'Despojar de vestiduras, desollar un animal o hacer una incursión repentina; abarca desvestirse, despojo forzado, desuello y asalto militar');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6585', 'spa', 'marchar, avanzar, dar pasos (forma cohortativa); aparece en Isaías 27:4 sobre marchar contra los enemigos', 'Este verbo significa ''dar pasos'', ''marchar'' o ''avanzar a grandes zancadas'', y aparece en forma cohortativa (primera persona expresando voluntad) en Isaías 27:4. El SEÑOR declara: ''No tengo ira. ¡Quién me diera espinos y zarzas en batalla! Yo marcharía contra ellos y los quemaría juntos''. El verbo transmite avance militar, el acto de lanzarse al combate contra los enemigos. La imagen presenta a Dios como guerrero dispuesto a luchar, aunque notablemente los enemigos mencionados son espinos y zarzas metafóricos que representan la oposición a su viña (Israel). La forma cohortativa expresa una disposición hipotética: si tales enemigos amenazaran la viña, Dios avanzaría contra ellos de manera decisiva.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6586', 'spa', 'Rebelarse, sublevarse contra la autoridad; transgredir la ley o el pacto divino; como sustantivo, transgresor o rebelde', 'Rebelarse, sublevarse contra la autoridad; transgredir la ley o el pacto divino; como sustantivo, transgresor o rebelde');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6587', 'spa', 'un paso (sustantivo); usado en la frase ''apenas hay un paso entre mí y la muerte'' en 1 Samuel 20:3', 'Este sustantivo significa ''paso'' o ''zancada'', y aparece únicamente en 1 Samuel 20:3, en la conversación entre Jonatán y David sobre la intención asesina de Saúl. David jura: ''Vive el SEÑOR y vive tu alma, que apenas hay un paso entre mí y la muerte''. La expresión ''un paso'' transmite una proximidad extrema: David está a una sola zancada de ser asesinado. La imagen es espacial: la muerte no es una posibilidad lejana, sino una amenaza inmediata, tan cercana como una pisada. Esta declaración dramática subraya la urgencia de la situación de David y su necesidad de que Jonatán le ayude a discernir las verdaderas intenciones de Saúl.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6588', 'spa', 'Entre los vocablos hebreos para el pecado, פֶּשַׁע conlleva la connotación más fuerte de desafío deliberado y voluntario. Mientras que חַטָּאת (''pecad', 'Entre los vocablos hebreos para el pecado, פֶּשַׁע conlleva la connotación más fuerte de desafío deliberado y voluntario. Mientras que חַטָּאת (''pecado'') implica errar el blanco y עָוֹן (''iniquidad'') apunta a una torcedura moral, פֶּשַׁע denota un acto de rebelión consciente contra una autoridad reconocida — preeminentemente Dios, pero también gobernantes humanos. Los oráculos de Amós contra las naciones lo emplean de forma formulaica (''por tres transgresiones y por cuatro,'' Am 1:3ss.), subrayando que incluso las naciones paganas son responsables. La palabra también aparece en los grandes textos confesionales de Israel (Éx 34:7; Nm 14:18), donde la disposición de Dios a perdonar פֶּשַׁע revela la gravedad de lo que se perdona.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6591', 'spa', 'interpretación — el significado de un sueño o visión, sustantivo arameo usado exclusivamente en Daniel', 'interpretación — el significado de un sueño o visión, sustantivo arameo usado exclusivamente en Daniel');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6592', 'spa', 'interpretación, solución (de un enigma o acertijo); préstamo del arameo que aparece en la literatura sapiencial', 'Esta palabra poco frecuente, tomada del arameo, conlleva el sentido de descifrar un misterio o resolver un enigma. En Eclesiastés 8:1 se pregunta quién conoce la interpretación de un asunto, es decir, la capacidad de desentrañar lo que permanece oculto tras las preguntas desconcertantes de la vida. La Biblia hebrea ocasionalmente adopta términos arameos para significados especializados, y aquí el préstamo enriquece el vocabulario sapiencial al centrarse en la habilidad interpretativa: la capacidad de dar sentido a lo que desconcierta a los demás.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6593', 'spa', 'Lino — la fibra vegetal y el textil tejido con ella. Abarca tanto la planta de lino cruda como el tejido de lino acabado sin distinción léxica entre a', 'Lino — la fibra vegetal y el textil tejido con ella. Abarca tanto la planta de lino cruda como el tejido de lino acabado sin distinción léxica entre ambos. Rahab esconde a los espías israelitas bajo tallos de lino secándose en su techo (Jos 2:6), mientras Sansón rompe sus ataduras de lino cuando el fuego las consume (Jue 15:14). En Oseas, el lino aparece junto a la lana como un producto natural valioso (Os 2:7, 11). La legislación sacerdotal empareja el lino y la lana en leyes de pureza sobre contaminación de vestiduras (Lv 13:47-59) y en la prohibición de telas mixtas (Dt 22:11). Los sacerdotes de Ezequiel deben vestir lino, no lana, al ministrar (Ez 44:17-18).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6594', 'spa', 'Lino (planta); también mecha de lino (fibra usada en lámparas)', 'Esta palabra designa la planta de lino en su estado de crecimiento o sus fibras procesadas como mechas de lámparas. Éxodo 9:31 menciona dos veces el cultivo de lino destruido por el granizo durante la séptima plaga. Isaías emplea la mecha de lino como metáfora: el ''lino humeante'' (43:17) y la ''mecha que se apaga'' (42:3) representan algo frágil, casi extinto, pero no del todo apagado. El Mesías no ''quebrará'' ni ''apagará'' esa débil esperanza. El material es el mismo; su aplicación varía desde la agricultura hasta la iluminación doméstica y la metáfora profética.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6595a', 'spa', 'Un bocado o fragmento de pan; un pequeño trozo de alimento compartido en hospitalidad o pobreza. Se refiere a un bocado, fragmento o pedazo de pan — l', 'Un bocado o fragmento de pan; un pequeño trozo de alimento compartido en hospitalidad o pobreza. Se refiere a un bocado, fragmento o pedazo de pan — la porción humilde que ancla escenas de hospitalidad y carencia a lo largo de las Escrituras. Abraham ofrece a los viajeros cansados un ''bocado de pan'' como modestia que encubre una generosidad abundante (Gn 18:5). Booz invita a Rut a mojar su bocado en vinagre durante la comida de la siega (Rt 2:14). La palabra tiene peso teológico en Proverbios: ''Mejor es un bocado seco con paz que una casa llena de banquetes con discordia'' (Pr 17:1). Job protesta su integridad jurando que nunca comió su bocado solo sin compartirlo con el huérfano (Job 31:17). El plural aparece en las regulaciones levíticas de la ofrenda de cereal para los pedazos partidos (Lv 2:6; 6:21).');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6595b', 'spa', 'pedazos (de pan); fragmentos usados en contexto metafórico de condenación profética', 'Esta forma plural constructa se refiere a pequeños trozos o migajas de pan, y aparece en la dura reprensión de Ezequiel contra los falsos profetas. El pasaje condena a quienes manipulan al pueblo de Dios a cambio de recompensas insignificantes: simples bocados de pan. La palabra captura tanto los fragmentos físicos como la mezquindad moral de vender la integridad espiritual por tan poca cosa. Es una imagen vívida: profetas que truecan la verdad por migajas.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6597', 'spa', 'De repente, inesperadamente — describe sucesos que golpean sin previo aviso, especialmente calamidades y acciones divinas', 'De repente, inesperadamente — describe sucesos que golpean sin previo aviso, especialmente calamidades y acciones divinas');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6598', 'spa', 'Manjar real; alimento selecto de la mesa del rey, préstamo persa usado exclusivamente en Daniel.', 'Préstamo del persa (cf. sánscrito prati-bhaga, ''una porción'') que designa los alimentos finos y manjares servidos en la mesa real. Aparece únicamente en Daniel, donde los jóvenes cautivos reciben la oferta de las provisiones del rey pero eligen abstenerse. La evidencia multilingüe es notablemente uniforme: español ''comida del rey'', inglés ''delicacy'' y francés ''nourriture'' apuntan a un significado único y claro. La palabra captura no solo el alimento en sí, sino también las implicaciones políticas y espirituales de aceptar la generosidad de un rey extranjero.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6600', 'spa', 'Palabra, decreto, mandato o comunicación oficial (préstamo arameo del persa)', 'Sustantivo arameo de origen persa (pitgam) que significa palabra, decreto o comunicación oficial. Abarca desde un mandato real (Esd 6:11) hasta correspondencia diplomática (Esd 4:17; 5:7), pasando por una respuesta formal (Esd 5:11) e incluso un sentido más general de ''asunto'' o ''cuestión'' (Dan 3:16; 4:17). El vocablo entró al arameo desde el antiguo persa patigama (''mensaje''), y su matiz burocrático encaja perfectamente en los contextos imperiales de Esdras y Daniel. Posteriormente pasó al hebreo rabínico como pitgam, con el sentido de dicho proverbial.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6601a', 'spa', 'ensanchar, hacer amplio o espacioso; principalmente expansión espacial pero puede aplicarse a abrir los labios al hablar', 'La raíz comunica hacer algo más ancho o más espacioso. En Génesis 9:27, la bendición de Noé pide a Dios que ''ensanche'' a Jafet—dándole territorio extenso. La palabra aparece en contextos sapienciales donde puede describir abrir ampliamente los labios (Proverbios 20:19, 24:28), ya sea literalmente o como metáfora del habla indiscreta. La evidencia multilingüe muestra tanto significados espaciales (alemán ''weit-mache'') como relacionados con el habla (español ''engañarás'', engañar), reflejando el rango desde la expansión física hasta la apertura figurativa de la boca.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6601b', 'spa', 'Seducir, persuadir, engañar; Nifal/Qal pasivo: ser engañado; participio Qal: simple, ingenuo', 'Seducir, persuadir, engañar; Nifal/Qal pasivo: ser engañado; participio Qal: simple, ingenuo');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6602', 'spa', 'Petuel, padre del profeta Joel; nombre que posiblemente significa ''apertura de Dios'' o ''persuadido por Dios''', 'Petuel es conocido únicamente como el padre del profeta Joel, mencionado en el versículo inicial de ese libro. Su nombre podría derivar de raíces que sugieren persuasión o apertura, aludiendo a revelación o capacitación divina. La Septuaginta lo traduce como Batuel, lo cual muestra cierta fluidez textual. Como muchas referencias patronímicas en los libros proféticos, Petuel sitúa al profeta dentro de un linaje familiar, otorgando autoridad y contexto histórico a los oráculos de Joel.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6603', 'spa', 'Grabado o inscripción tallada, especialmente los grabados en gemas de las vestiduras sacerdotales.', 'Se refiere al oficio especializado de incidir diseños o letras en materiales duros como piedra y metal. Casi todas las apariciones se concentran en Éxodo 28 y 39, donde se describen las gemas grabadas del pectoral y el efod del sumo sacerdote: cada piedra lleva el nombre de una tribu tallado como un sello de anillo. El término español «grabado» y el inglés «engraving» resaltan la cualidad incisa y permanente de la obra, propia de inscripciones destinadas a perdurar ante la presencia de Dios.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6605a', 'spa', 'Abrir, soltar, liberar — verbo de abrir puertas, puertas de ciudad, recipientes, ataduras; Piel = desatar/liberar; incluye desenvainar una espada', 'Este verbo (136 veces) significa primordialmente ''abrir'' en Qal: puertas, ventanas, sacos, ojos, bocas. El Nifal es el pasivo (''ser abierto''), el Piel intensifica hacia ''soltar, desatar'' ligaduras o ''liberar'' cautivos, y el Hitpael es reflexivo (''soltarse a sí mismo''). Un sentido especializado es ''desenvainar una espada'' de su vaina. Los paralelos multilingües —árabe فَتَحَ (abrir) y حَلَّ/فَكَّ (soltar), coreano 열다 (abrir) y 풀다 (soltar), suajili -fungua (abrir/desatar), español abrir y soltar/desatar— distinguen claramente ''abrir'' de ''soltar'', confirmando dos núcleos semánticos. El participio pasivo פָּתוּחַ significa ''que permanece abierto''.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6605b', 'spa', 'Grabar o cincelar diseños en piedra, metal o madera, especialmente para las vestiduras sacerdotales y el mobiliario del templo', 'Verbo en Piel distinto de פָּתַח I (''abrir''), esta raíz se refiere al oficio especializado de grabar inscripciones y motivos decorativos sobre superficies duras. Aparece en Éxodo para el grabado de los nombres tribales en las piedras de ónice del sumo sacerdote y la inscripción de la placa de oro ''Santo a YHWH'' (Éx 28:9-11, 36), y en Reyes y Crónicas para la ornamentación del templo (1 R 7:36; 2 Cr 3:7). Zacarías 3:9 lo emplea metafóricamente para Dios grabando una piedra. El español ''grabó'' y el inglés ''engrave'' captan consistentemente este sentido artesanal especializado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6607', 'spa', 'Abertura, entrada, puerta; el paso de acceso a una tienda, casa, templo o ciudad; ocasionalmente la puerta como estructura física', 'El término hebreo estándar para designar una entrada o vano de puerta: el espacio por el que se pasa para entrar a una tienda, casa, templo, cueva o ciudad. Aparece de modo memorable como ''la entrada de la tienda'' donde Abraham recibe a sus visitantes (Gn 18:1) y ''la entrada del Tabernáculo de Reunión'' en la legislación sacerdotal. Un grupo secundario lo emplea para la puerta como objeto físico, algo que puede abrirse, cerrarse o untarse con sangre (Éx 12:22-23). El inquietante ''el pecado está agazapado a la puerta'' de Gn 4:7 explota magistralmente la ambigüedad entre paso y barrera.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6608', 'spa', 'apertura, despliegue; la revelación o manifestación de las palabras que trae iluminación', 'Este sustantivo denota el acto de abrir o desplegar, y se usa metafóricamente en el Salmo 119 para referirse a la revelación de la palabra de Dios. Cuando las Escrituras se abren o despliegan, la luz irrumpe y amanece la comprensión. No se trata simplemente de leer, sino del momento en que el significado se vuelve luminoso. Algunas versiones antiguas lo interpretaron literalmente como una puerta, pero la mayoría de tradiciones lo entienden como el acto dinámico de revelación que transforma la oscuridad en discernimiento.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6609', 'spa', 'espadas desenvainadas; metafóricamente, palabras afiladas y cortantes que hieren', 'Esta forma plural se refiere a espadas que han sido desenvainadas, listas para la violencia. En el Salmo 55, la imagen se aplica de manera impactante al habla: las palabras de compañeros traicioneros son como espadas desenvainadas, cortantes y mortales. La metáfora es poderosa: el lenguaje como arma, labios suaves que ocultan una intención letal. Otros salmos emplean imágenes similares, pero aquí la especificidad de «desenvainadas» subraya la disposición y el daño inminente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6611', 'spa', 'Petajías (nombre propio que significa ''Yahvé abre/libera'')', 'Nombre propio llevado por tres individuos distintos en el período postexílico. Un Petajías fue sacerdote cuya división servía en la organización litúrgica de David (1 Crónicas 24:16). Otro fue un levita que participó en la confesión y renovación del pacto bajo Esdras (Esdras 10:23; Nehemías 9:5). Un tercero sirvió como comisionado real de Judá bajo la administración persa (Nehemías 11:24). El nombre significa ''Yahvé abre'' o ''Yahvé libera'', reflejando la piedad postexílica y la esperanza en la liberación divina.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6612a', 'spa', 'Simple, ingenuo, crédulo — persona sin experiencia, abierta a influencias tanto positivas como negativas, en la literatura sapiencial', 'Simple, ingenuo, crédulo — persona sin experiencia, abierta a influencias tanto positivas como negativas, en la literatura sapiencial');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6612b', 'spa', 'simpleza, ingenuidad; el estado de carecer de sabiduría y discernimiento', 'Este sustantivo abstracto expresa la cualidad de ser simple o ingenuo, no en un sentido inocente, sino como la condición problemática de carecer de sabiduría. En Proverbios, los simples son aquellos que aún no han elegido el camino del entendimiento y permanecen vulnerables a la necedad por no haber desarrollado discernimiento. La palabra describe un estado que puede remediarse mediante la instrucción, pero que también representa una peligrosa vulnerabilidad. La literatura sapiencial exhorta reiteradamente a los simples a despertar y abrazar la sabiduría.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6614', 'spa', 'vestidura lujosa, prenda elaborada; probablemente un artículo de lujo importado usado por mujeres adineradas', 'Esta palabra rara, probablemente tomada de otra lengua, designa una prenda costosa y elaborada. Aparece en el catálogo de Isaías sobre los adornos femeninos que serán despojados en el juicio divino. Las versiones antiguas vacilaron en su traducción: la Septuaginta ofreció «túnica púrpura» y la Vulgata «cinta de pecho». Esa incertidumbre refleja la rareza y el origen extranjero del término, pero el contexto deja claro que se trata de un artículo de lujo, símbolo de la vanidad y el exceso que Isaías condena.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6615', 'spa', 'simpleza, ingenuidad; alternativamente, cualidad seductora (en sentido personificado)', 'Este sustantivo abstracto, estrechamente emparentado con la palabra para «ingenuo», puede significar tanto la cualidad de la ingenuidad como, según el contexto, una simpleza seductora. En Proverbios 9, aparece en la descripción de la Necedad como mujer seductora. Algunos traductores han enmendado el texto, pero la lectura recibida sugiere que la Necedad encarna un atractivo peligroso que cautiva a los ingenuos. El vocablo tiende así un puente entre la ingenuidad intelectual y el peligro moral.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6616', 'spa', 'Cordón o hilo torcido, usado para atar, sujetar vestiduras sacerdotales, medir, y como figura de atadura frágil.', 'De la raíz p-t-l (''torcer''), este sustantivo designa un tramo de fibra torcida. Su uso más destacado aparece en las normas del tabernáculo, donde un petil tekhelet (''cordón de azul'') sujeta el pectoral al efod (Éx 28:28, 37; 39:21, 31) y se coloca en los flecos del manto de cada israelita (Nm 15:38). Judá entrega su petil —aparentemente un cordón personal distintivo, quizá del que colgaba su sello— como prenda a Tamar (Gn 38:18, 25). Ezequiel 40:3 describe una línea de medir de hilo de lino (petil pishtim), mientras que Jueces 16:9 lo usa como símil de rotura sin esfuerzo: Sansón rompe sus ataduras «como un hilo de estopa».');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6617', 'spa', 'Torcer, luchar; en Nifal/Hitpael, ser tortuoso, obrar con astucia o perversidad', 'Verbo que significa torcer, con aplicaciones tanto físicas como morales. La declaración de Raquel «Con luchas de Dios he luchado» (Gn 30:8) emplea el Nifal para expresar un forcejeo personal intenso. En la literatura sapiencial, el participio Nifal describe lo tortuoso o retorcido: los planes del astuto (Job 5:13) y el habla perversa y torcida (Pr 8:8). El Hitpael en los salmos expresa la respuesta recíproca de Dios: «con el torcido te muestras sagaz» (Sal 18:26; 2 Sam 22:27), igualando la perversidad con sabiduría inescrutable.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6618', 'spa', 'torcido, retorcido, perverso; contorsionado moral y físicamente', 'Este adjetivo describe lo que está torcido o tortuoso, empleado tanto en sentido literal como figurado. En Deuteronomio 32, caracteriza a una generación moralmente retorcida y perversa, lo opuesto a la rectitud de Dios. La imagen es visceral: algo deformado de su forma verdadera, que rehúsa el camino recto. Es un término predilecto de la literatura sapiencial para referirse a la desviación moral, captando no solo la mala conducta sino una distorsión fundamental de lo que debería ser recto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6619', 'spa', 'Pitom, una de las ciudades de almacenaje egipcias construidas por los israelitas esclavizados bajo Faraón', 'Pitom fue una de las ciudades de almacenaje que los israelitas esclavizados fueron obligados a construir para Faraón, mencionada junto a Ramsés en Éxodo. La investigación arqueológica e histórica la identifica con el egipcio Per-Atum (Casa de Atum, una deidad solar), probablemente ubicada en Tel el-Maskuta, en la región del Wadi Tumilat en Egipto. El nombre preserva la memoria del trabajo brutal y la opresión, un símbolo de la esclavitud de Israel que hace del Éxodo un acontecimiento aún más portentoso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6620', 'spa', 'Cobra o serpiente venenosa (peten); símbolo poético de veneno mortal y peligro letal', 'Serpiente venenosa, muy probablemente la cobra egipcia (Naja haje), que aparece exclusivamente en textos poéticos y proféticos como potente símbolo de peligro mortal. El cántico de Moisés compara el vino de los malvados con el veneno de los petanim (Dt 32:33). Job equipara el pecado oculto con veneno de cobra absorbido y tragado (Job 20:14, 16). Los Salmos la emparejan con otras criaturas temibles: la víbora sorda que se tapa el oído (Sal 58:4) y el león y dragón que los fieles pisotearán (Sal 91:13). La visión mesiánica de Isaías muestra a un niño jugando sin peligro junto a la cueva de la cobra (Is 11:8), transformando el símbolo de muerte en señal del paraíso restaurado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6621', 'spa', 'De repente, en un instante; denota una ocurrencia inesperada y abrupta.', 'Adverbio que expresa una acción repentina e inesperada — algo que sucede sin aviso ni preparación. A menudo se empareja con el cuasi-sinónimo פִּתְאֹם para dar fuerza enfática (''muy de repente'', Nm 6:9). Aparece en contextos legales para el daño accidental (Nm 35:22), en oráculos proféticos para el juicio divino veloz (Is 29:5; 30:13; Hab 2:7), y en la literatura sapiencial para la ruina abrupta del insensato (Pr 6:15; 29:1). Las traducciones al español — ''de repente'', ''súbitamente'' — confirman el significado constante en todas las ocurrencias.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6622', 'spa', 'Interpretar sueños o visiones; usado exclusivamente en la narrativa de José (Génesis 40-41).', 'Este verbo aparece únicamente en Génesis 40-41, donde José interpreta los sueños del copero y el panadero de Faraón, así como los del propio Faraón. Es funcionalmente equivalente al arameo peshar (''disolver, resolver''), lo cual sugiere la metáfora semántica de ''desentrañar'' el significado oculto de un sueño. Las traducciones en español (''interpretó'') y en alemán (''deutete'') captan con precisión el acto declarativo de revelar lo que un sueño significa. La insistencia repetida de José en que las interpretaciones pertenecen a Dios (Gn 40:8) otorga a esta palabra un peso teológico que trasciende la mera habilidad humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6623', 'spa', 'Interpretación (de un sueño); el significado revelado de una experiencia visionaria', 'Sustantivo empleado exclusivamente en las narraciones de José en Génesis 40-41, que denota la interpretación o significado revelado de un sueño. El copero y el panadero del faraón tuvieron cada uno un sueño con su propio pitrón, y José insistió en que las interpretaciones pertenecen solo a Dios (Gn 40:8). La evidencia multilingüe es notablemente uniforme: el español «interpretación», el francés «interprétation» y el alemán «Deutung» convergen en un único núcleo semántico. La palabra deriva de la raíz ptr («abrir, revelar»), sugiriendo el desvelamiento de un significado oculto.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6624', 'spa', 'Patros; Alto Egipto, la región meridional del valle del Nilo', 'Patros designa el Alto Egipto (la zona sur), derivado del egipcio p-tĕ-res que significa «la tierra del sur». Aparece en la literatura profética siempre en conexión con Egipto (mitsráyim), distinguiendo la región meridional del Nilo del Bajo Egipto y el Delta. Isaías 11:11 lo incluye entre las tierras del futuro reagrupamiento de Israel, mientras que Ezequiel 29:14 lo llama la patria ancestral de Egipto. Jeremías 44:1, 15 sitúa allí a los refugiados judíos tras la caída de Jerusalén.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6626', 'spa', 'desmenuzar, partir en pedazos (infinitivo absoluto); partir pan en trozos pequeños', 'Este verbo significa partir en trozos pequeños o desmenuzar, usado particularmente con referencia al pan. En Levítico 2:6, aparece en las instrucciones para la ofrenda de cereal: el adorador debe desmenuzar la torta sin levadura en pedazos. El infinitivo absoluto intensifica la acción: «ciertamente la partirás en trozos». Es un verbo de fragmentación física, que convierte lo entero en muchas partes, y en el contexto sacrificial se transforma en un acto de adoración y consagración.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6629', 'spa', 'Rebaño, ganado menor; término colectivo para ovejas y cabras como grupo', 'Sustantivo colectivo que aparece 274 veces. Designa ovejas y cabras vistas conjuntamente como rebaño, el ganado menor básico de la vida pastoril del antiguo Israel. Abarca rebaños literales en el pastoreo (Gn 30:31-32), animales seleccionados para el sacrificio, riqueza medida en hatos (Gn 24:35; 26:14) y la poderosa metáfora del pueblo de Dios como su rebaño (Sal 100:3; Ez 34). El vocablo nunca individualiza ovejas o cabras por separado, sino que siempre las contempla como unidad colectiva. El alemán distingue Schafe de Ziegen, pero traduce este término simplemente como Schafe, reflejando la asociación predominante con las ovejas dentro del colectivo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6630', 'spa', 'Zaanán, ciudad mencionada en el oráculo de juicio de Miqueas, posiblemente idéntica a Zenán en Judá', 'Zaanán es una ciudad nombrada en el lamento de Miqueas sobre las ciudades de Judá, un pasaje cargado de juegos de palabras proféticos. El profeta aprovecha la semejanza entre el nombre de la ciudad y el verbo «salir» para crear un sombrío juego de palabras: los habitantes de Zaanán no saldrán, atrapados en su propio juicio. Algunos estudiosos la identifican con Zenán, en las tierras bajas de la Sefela de Judá. Aunque la versión de la Septuaginta refleja cierta incertidumbre textual, la fuerza retórica del oráculo de Miqueas resulta clara en cualquier caso.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6631', 'spa', 'Vástagos, descendencia, producto — descendientes de personas o brotes de la tierra, siempre en forma plural.', 'Este sustantivo, que aparece siempre en plural, (de la raíz y-ts-'') abarca tanto la progenie humana como los frutos de la tierra. En su sentido predominante funciona como paralelo de zera'' (''semilla/descendencia'') y banim (''hijos''): Isaías 48:19 lo empareja directamente — «tu descendencia (tse''etsa''e me''ekha) sería como la arena» — y Job 5:25 promete que «tus vástagos serán muchos». La palabra porta un matiz orgánico, casi vegetal, incluso cuando se aplica a personas, como si los hijos «brotaran» del cuerpo. En dos pasajes (Is 34:1; 42:5), el referente se desplaza hacia el producto o la vegetación de la tierra.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6632b', 'spa', 'lagarto grande, tipo de reptil de gran tamaño incluido entre los animales impuros', 'Este término designa una especie de lagarto grande, clasificado en Levítico como ritualmente impuro. La identificación exacta es debatida: las posibilidades incluyen un varano, un gecko u otro reptil de buen tamaño común en la región. La palabra forma parte de una lista detallada que distingue animales puros de impuros, reflejando los códigos de pureza y alimentación del antiguo Israel. Aunque la especie precisa sigue siendo incierta, la categoría es clara: un reptil terrestre fuera de los límites del alimento permitido.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6633', 'spa', 'Verbo hebreo cuyo campo semántico une el campo de batalla y el santuario bajo una misma raíz. En su sentido marcial, צָבָא describe ejércitos que sale', 'Verbo hebreo cuyo campo semántico une el campo de batalla y el santuario bajo una misma raíz. En su sentido marcial, צָבָא describe ejércitos que salen a guerrear (Nm 31:7; Is 29:7-8), y la evidencia multilingüe es contundente: español guerrear, hindi yuddh karna, árabe haraba y suajili kupigana convergen en el conflicto armado. Sin embargo, la misma raíz en Éxodo 38:8 describe a las mujeres que ''servían'' a la entrada del Tabernáculo de Reunión, un uso que el español servir y el hindi seva karna expresan con suave domesticidad. La conexión no es casual: tanto el soldado como el asistente del templo pertenecen a un ''ejército'' (צָבָא) organizado que realiza servicio disciplinado bajo autoridad. Un tercer sentido más raro en Hifil —alistar o reclutar tropas, como en 2 Reyes 25:19 y Jeremías 52:25— completa el cuadro de movilizar recursos humanos para la acción colectiva, ya sea sagrada o militar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6634', 'spa', 'Querer, desear o complacerse; usado para expresar la voluntad divina y real en las porciones arameas de Daniel.', 'Verbo arameo que aparece exclusivamente en el libro de Daniel, expresando un acto deliberado de voluntad, deseo o elección. Cuando se emplea con referencia a Dios (Dn 4:17, 25, 32), transmite su autoridad soberana sobre todos los reinos terrenales: ''Él hace según su voluntad.'' Cuando se refiere a Nabucodonosor (Dn 5:19), describe el poder absoluto de un rey que podía elevar o destruir a su antojo. Las traducciones en español ''quiere'' y ''quería'', así como el alemán Willen, convergen en esta misma idea central de volición deliberada, ya sea divina o humana.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6635', 'spa', 'ejércitos, huestes; frecuente en el título divino «SEÑOR de los Ejércitos» (צְבָאוֹת)', 'La forma plural significa ejércitos o huestes, y es célebre sobre todo en el título divino «SEÑOR de los Ejércitos», que presenta a Dios como comandante de los ejércitos celestiales y terrenales. Esta ocurrencia conserva ese peso teológico, subrayando el poder soberano de Dios. El término puede referirse a las huestes angélicas, a los ejércitos de Israel o incluso a las estrellas, todos bajo mando divino. Es una imagen militarista que, no obstante, asegura a los creyentes la fuerza abrumadora de Dios en defensa de su pueblo.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6635a', 'spa', 'Ejército, hueste o fuerza organizada; también servicio forzado, deber obligatorio o campaña militar como actividad', 'En su núcleo, este vocablo designa un cuerpo organizado de personas movilizado con un propósito, casi siempre militar. Aparece con frecuencia en la fórmula ''YHWH de los ejércitos'' (Yhwh tseva''ot), donde abarca ejércitos celestiales, seres angélicos e incluso las estrellas. Más allá de la hueste militar, el término se extiende a la dura realidad del servicio obligatorio y el trabajo forzado, como cuando Job lamenta que la vida humana sobre la tierra es como un servicio militar (Job 7:1). Isaías emplea la misma metáfora al declarar que la ''milicia'' de Jerusalén ha terminado (Is 40:2). El arco semántico desde ''ejército'' hasta ''servicio penoso'' refleja un mundo antiguo donde la conscripción era la carga definitoria de la existencia.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6635b', 'spa', 'Ejércitos, huestes (de YHWH) — las fuerzas celestiales o militares invocadas en el título divino ''Señor de los Ejércitos''', 'Forma plural de tsava'' (''ejército, hueste'') que aparece abrumadoramente en el epíteto divino YHWH Tseva''ot, ''el Señor de los Ejércitos''. De sus 286 ocurrencias, la inmensa mayoría pertenece a este título, que domina los libros proféticos (Isaías, Jeremías, Hageo, Zacarías, Malaquías). Las ''huestes'' se han entendido diversamente como los ejércitos de Israel, los seres angélicos o las fuerzas cósmicas del cielo. El alemán Heerscharen (''multitudes de huestes'') y el francés armées conservan la imaginería militar, mientras que las transliteraciones españolas e inglesas ''Tsevaot/Tsebaot'' reconocen que ningún vocablo aislado captura el peso teológico del título.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6636', 'spa', 'Zeboiim — una de las cinco ciudades de la llanura destruidas con Sodoma y Gomorra; también nombre de un valle en Benjamín.', 'Zeboiim (también escrito Zeboim) es un topónimo que identifica principalmente una de las cinco ciudades de la llanura del Jordán que compartió el destino de Sodoma y Gomorra. Aparece en la Tabla de las Naciones delimitando el territorio cananeo (Gn 10:19), en la narrativa bélica de Génesis 14 donde su rey Shemeber se unió a la coalición (Gn 14:2, 8), y en la advertencia de Moisés sobre la destrucción del territorio como Sodoma, Gomorra, Admá y Zeboiim (Dt 29:23). Su aparición más conmovedora es Oseas 11:8, donde la angustia de Dios ante la posibilidad de destruir a Efraín se expresa con la pregunta: «¿Cómo podré hacerte como Admá? ¿Cómo podré tratarte como a Zeboiim?». Un lugar distinto llamado Valle de Zeboim aparece en 1 Samuel 13:18 y Nehemías 11:34.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6637', 'spa', 'Zobeba (o Tsobeba), nombre propio en las genealogías de Judá', 'Zobeba aparece en los registros genealógicos de Judá en 1 Crónicas. El nombre no se menciona en ningún otro lugar, y las variantes de la Septuaginta reflejan cierta incertidumbre textual. Como muchos nombres en las genealogías de Crónicas, sirve para trazar las relaciones entre clanes y preservar la memoria tribal, aun cuando no disponemos de más relatos sobre este individuo. Estas listas, aunque densas, arraigan la historia de Israel en familias y lugares reales.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6639', 'spa', 'hinchado, tumefacto (adjetivo); describe la distensión corporal como efecto de una maldición', 'Este adjetivo describe un estado de hinchazón o distensión, empleado en el ritual de los celos en Números. Si la mujer acusada de adulterio es culpable, la maldición hará que su cuerpo se hinche, una señal física gráfica y específica del juicio divino. La palabra capta la manifestación visible de la culpa, un síntoma corporal imposible de ocultar. Forma parte de un antiguo ritual de ordalia en el que el propio cuerpo atestigua la verdad o la falsedad.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6640', 'spa', 'cosa, asunto, propósito; cualquier objeto o preocupación (préstamo del arameo)', 'Este término arameo, que aparece en Daniel, significa cosa, asunto o propósito: esencialmente cualquier cosa que ocupe la mente o requiera acción. En Daniel 6, se refiere al estado mental del rey: ningún entretenimiento ni distracción pudo ser traído ante él mientras se angustiaba por Daniel en el foso de los leones. La amplitud semántica del vocablo es su mayor virtud: puede referirse a comida, música o cualquier inquietud. Formas afines en palmireno y siríaco confirman su extenso rango de significado.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6641', 'spa', 'moteado, abigarrado; que presenta colores o patrones diversos', 'Este adjetivo describe algo marcado con colores variados o manchas: moteado o abigarrado. En Jeremías 12:9, aparece en un versículo enigmático sobre un «ave de rapiña moteada» que se convierte en blanco de otras aves. La imagen sugiere algo inusual o llamativo, que destaca de un modo que atrae hostilidad. Los comentaristas debaten la metáfora exacta, pero la palabra denota claramente distinción visual: un patrón y colorido que marcan algo como diferente.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6642', 'spa', 'extender, alcanzar, entregar; tender algo a otra persona con la mano', 'Este verbo significa extender o alcanzar algo a alguien, particularmente con la mano. En Rut 2:14, Booz le alcanza grano tostado a Rut, un gesto de provisión y aceptación. La raíz podría estar relacionada con asir o sostener, y cognados en árabe sugieren un manejo firme. Es un verbo de interacción social: el acto físico de dar que encarna bondad e inclusión.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6643a', 'spa', 'Belleza, esplendor, gloria; también la gacela como emblema de gracia; usado como epíteto de la Tierra Prometida', 'Belleza, esplendor, gloria; también la gacela como emblema de gracia; usado como epíteto de la Tierra Prometida');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6643b', 'spa', 'Designa a la gacela (Gazella), uno de los animales más evocadores de la Biblia hebrea. Deuteronomio la incluye entre los animales limpios permitidos c', 'Designa a la gacela (Gazella), uno de los animales más evocadores de la Biblia hebrea. Deuteronomio la incluye entre los animales limpios permitidos como alimento junto con el ciervo (Dt 12:15, 22; 14:5; 15:22), y aparece en la lista de provisiones diarias de Salomón (1 R 4:23). Más allá de la mesa, la gacela se convierte en imagen literaria de rapidez extraordinaria: Asael era ''ligero de pies como una gacela salvaje'' (2 S 2:18), y los guerreros eran ''veloces como gacelas en los montes'' (1 Cr 12:8). En el Cantar de los Cantares, la gacela encarna la belleza y la gracia románticas (Cnt 2:9, 17; 8:14) y solemnemente conjura a las hijas de Jerusalén (Cnt 2:7; 3:5). El cognado árabe ظبي (ẓaby) confirma la identificación.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6644', 'spa', 'Tsibia, nombre propio en la tribu de Benjamín', 'Tsibia aparece entre los benjaminitas en las genealogías de Crónicas. El nombre podría derivar de una raíz relacionada con gacelas o belleza, aunque su etimología es incierta. Como ocurre con muchos nombres genealógicos, no sabemos nada del individuo más allá de esta mención. Las variadas grafías de la Septuaginta reflejan los desafíos de transliterar nombres hebreos, pero el nombre se conserva como parte del registro tribal de Benjamín.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6647', 'spa', 'Ser mojado, empapado (con rocío); mojar o empapar a alguien', 'Verbo arameo que aparece exclusivamente en Daniel 4-5, describiendo cómo el cuerpo de Nabucodonosor fue empapado con el rocío del cielo durante su período de locura entre las bestias. La forma activa Pael significa ''mojar, empapar a alguien'', mientras que la pasiva Hitpaal significa ''ser mojado''. La frase recurrente ''mojado con el rocío del cielo'' transmite con fuerza la exposición total del rey a los elementos como juicio divino. Las cinco apariciones se concentran en esta narrativa única de degradación real.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6648', 'spa', 'tela teñida, vestiduras teñidas; tela coloreada, especialmente como botín valioso o adorno fino', 'Este término se refiere a tela que ha sido teñida—una marca de valor y lujo en el mundo antiguo. Las tres ocurrencias aparecen en Jueces 5:30, el cántico de victoria de Débora imaginando a la madre de Sísara esperando que su hijo regrese con botín. La repetición de ''tela teñida'' enfatiza la riqueza anticipada: vestiduras coloreadas con tintes preciosos. Translingüísticamente, las traducciones consistentemente presentan esto como tela teñida o coloreada (español ''tela teñida'', francés ''vêtement teint'', alemán ''gefärbtes Gewand''), subrayando que el teñido transformaba la tela ordinaria en bienes preciados.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6649', 'spa', 'Zibeón — jefe de clan horeo/heveo en las genealogías de Esaú y Seir, posiblemente significa «hiena».', 'Zibeón es un jefe de clan horeo que aparece exclusivamente en las genealogías de Esaú y de los habitantes originarios de Seir (Gn 36; 1 Cr 1:38, 40). Se lo identifica como hijo horeo de Seir (Gn 36:20, 29) y como padre de Oholibama, una de las esposas de Esaú (Gn 36:2, 14). Su hijo Aná es recordado por haber descubierto fuentes termales en el desierto mientras pastoreaba asnos (Gn 36:24), un detalle que da vida a estas listas genealógicas habitualmente escuetas. El BDB relaciona el nombre con la palabra hebrea para «hiena», un nombre animal apropiado para un clan de las escarpadas tierras altas de Seir.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6651', 'spa', 'Amontonar, acumular, almacenar en gran cantidad.', 'Verbo que significa apilar o acumular algo en abundancia. Su uso más memorable es el de José amontonando grano «como la arena del mar» durante los siete años de abundancia en Egipto (Gn 41:35, 49). También describe a los israelitas amontonando ranas muertas tras la plaga (Éx 8:14), a Tiro acumulando plata como polvo (Zac 9:3) y la futilidad de los impíos que amontonan riquezas que nunca disfrutarán (Job 27:16; Sal 39:6). El cognado árabe dabara («reunir, atar junto») confirma la semántica central de reunir y apilar.');
INSERT OR REPLACE INTO lemma_entry_translation_chirho (lemma_id_chirho, language_code_chirho, gloss_terse_chirho, gloss_readable_chirho) VALUES ('H6652', 'spa', 'montones, pilas; específicamente, pilas de cabezas cortadas en 2 Reyes', 'Este sustantivo plural significa montones o pilas, usado para objetos acumulados. En el relato estremecedor de 2 Reyes 10, se refiere a dos montones de cabezas cercenadas: los hijos de Acab, asesinados como parte de la purga de Jehú. La palabra es cruda y literal, subrayando el horror de la escena. Los montones pueden ser algo neutral (pilas de grano, por ejemplo), pero aquí el contexto los convierte en un monumento a la violenta convulsión política y la aniquilación dinástica.');